window.AS_SEARCH_INDEX=(window.AS_SEARCH_INDEX||[]).concat([{"p":"appendix/glossary.html","n":"A 术语表：中英对照 + 一句话直觉","s":"how","t":"怎么用这张表","x":"先看「一句话直觉」那一列 。名字只是索引，直觉才是能用的东西 标 ★ 的是必须能脱口而出的：说不清它们，后面的章节会一直卡 「章」这一列是第一次系统讲它的地方；附录只负责提醒，不负责讲透 表里出现的类名都可以在源码里搜到，包路径统一是 io.agentscope.core.* ，Harness 的在 io.agentscope.harness.agent.* 三对最容易混的概念，先在这里分清 State vs Memory ： AgentState 是「一份会话的全部可存内容」， Memory 只是其中「进上下文的那串消息」。 Hook vs Middleware ：Hook 是 切点回调 （到点叫你）， Middleware 是 包裹层 （能改写这一段怎么做）。 Event vs HookEvent ： AgentEvent 是 给外部消费者 的事件流， HookEvent 是 给框架内部 Hook 的切点对象，两套类型不通。"},{"p":"appendix/glossary.html","n":"A 术语表：中英对照 + 一句话直觉","s":"agent","t":"Agent 与运行时","x":"术语 中文 一句话直觉 章 Agent ★ 智能体接口 只承诺四件事：能 call 、能被 observe 、有旧版 stream 、能发事件； streamEvents 不在这个接口上 10 AgentBase 智能体基类 所有 agent 的共同底座：生命周期、Hook 分发、错误兜底、优雅停机登记 10 ReActAgent ★ ReAct 引擎 唯一的内置循环实现：「推理 → 调工具 → 再推理」，全站 18 章的每个能力最后都落到它 02 HarnessAgent ★ Harness 外壳 不是 ReActAgent 的子类 ：它 implements Agent, AutoCloseable ，内部持有一个 delegate 10 delegate 被委托者 Harness 内部真正在跑循环的那个 ReActAgent 实例；Harness 只做转发和加装 10 RuntimeContext ★ 运行时上下文 一次调用的「我是谁、在哪个会话」： userId + sessionId ，每次调用都可以不同 02 session 会话 就是 (userId, sessionId) 这对坐标；换坐标 = 换一份记忆，换一份权限规则 07 AgentRun 一次运行 描述某一次调用处在哪个阶段（排队 / 运行 / 完成 / 失败），不是「会话」 10 RunControl 运行控制 决定这次调用是排队、开跑还是被取消；中断能否生效取决于它此刻的状态 10 interrupt() 中断 让正在跑的循环在下一个检查点停下，结果消息的 reason 是 INTERRUPTED 10 graceful shutdown 优雅停机 JVM 要关时，先把在跑的请求收尾并落盘，而不是直接掐掉 10 Agent 的三个父接口： Agent.java:47 ； AgentBase ： AgentBase.java:91 ； HarnessAgent 的声明： HarnessAgent.java:169"},{"p":"appendix/glossary.html","n":"A 术语表：中英对照 + 一句话直觉","s":"message","t":"消息与内容块","x":"术语 中文 一句话直觉 章 Msg ★ 消息 对话的最小单位： role + 内容块列表 + metadata ； getTextContent() 在没有文本时返回 空串 而不是 null 04 MsgRole 消息角色 只有四个： USER / ASSISTANT / SYSTEM / TOOL 04 ContentBlock ★ 内容块 一条消息里可以 同时 有文本、思考、工具调用、图片——不是一个消息一种类型 04 TextBlock 文本块 你看到的「回答正文」 04 ThinkingBlock 思考块 推理模型的思维链； 存进记忆，但不会再发给模型 04 ToolUseBlock ★ 工具调用块 模型说「我要调这个工具」： id / name / input / state ，HITL 全靠 id 对齐 04 ToolResultBlock 工具结果块 工具执行后的结果：内容块 + ToolResultState + 关联的调用 id 04 DataBlock 数据块 图片 / 音频 / 视频 / 文件的统一容器（旧的 ImageBlock 等还在，但新代码用它） 04 HintBlock 提示块 中间件或 RAG 插进来的「背景提示」，不算对话历史，也不会污染 assistant 正文 04 ToolCallState 调用状态 PENDING → ASKING / ALLOWED ， ASKING 就是「等你批」； SUBMITTED 、 FINISHED 在 2.0.4 未使用 08 ToolResultState 结果状态 SUCCESS / ERROR / INTERRUPTED / DENIED / RUNNING 04 GenerateReason ★ 结束原因 这一轮为什么停下来，12 个枚举值； 判断是否暂停只能看它 04 metadata 元数据 挂在消息上的字典；HITL 的 ConfirmResult 就藏在 Msg.METADATA_CONFIRM_RESULTS 这个 key 下 08 MsgRole 只有 4 个值： MsgRole.java:35 ； GenerateReason ： GenerateReason.java:36 ； ToolCallState ： ToolCallState.java:20 ； ToolResultState ： ToolResultState.java:20 ；思考块不回传： AbstractBaseFormatter.java:121 GenerateReason 的 12 个值，一次看全 值 含义 你该做什么 MODEL_STOP 模型正常说完 结束，读文本 TOOL_CALLS 模型给了工具调用，框架继续跑 通常不会作为最终结果出现 STRUCTURED_OUTPUT 结构化输出完成 从 metadata 取结构化数据 TOOL_SUSPENDED 工具主动挂起，等外部结果 按 ExternalExecutionResultEvent 的约定回填 REASONING_STOP_REQUESTED Hook 在推理阶段叫停 看自己的 Hook 逻辑 ACTING_STOP_REQUESTED Hook 在行动阶段叫停 看自己的 Hook 逻辑 PERMISSION_ASKING 权限引擎要你确认 收集 ASKING 工具，回传 ConfirmResult MIDDLEWARE_STOP_REQUESTED 中间件请求暂停 无参数再调一次 call() 继续 ALL_TOOLS_DENIED 这轮工具全被拒，且 Hook 叫停 换策略或换提示词 INTERRUPTED 被 interrupt() 打断 决定重试还是放弃 MAX_ITERATIONS 撞到 maxIters 框架会多做一次摘要调用；调大上限或简化任务 TOOL_RETURN_DIRECT 工具结果直接当最终答案 不用再等模型说话"},{"p":"appendix/glossary.html","n":"A 术语表：中英对照 + 一句话直觉","s":"model","t":"模型层","x":"术语 中文 一句话直觉 章 Model ★ 模型接口 框架对 LLM 的唯一抽象：收一串 Msg ，回一个 ChatResponse 05 ChatModelBase 模型基类 各家 provider 的公共底座：超时、重试、流式拼装都在这里 05 ModelRegistry ★ 模型注册表 把 \"dashscope:qwen-plus\" 解析成实例；解析不了就抛 Cannot resolve model 05 ModelProvider 模型提供者 SPI 接口：扩展模块实现它，就能让某个前缀的 id 被解析 05 GenerateOptions 生成参数 温度、topP、maxTokens、 responseFormat 这些「不是模型 id 的东西」 05 ToolChoice 工具选择 强制调工具 / 禁止调工具 / 交给模型自己决定 05 ToolSchema 工具说明书 发给模型的 JSON Schema，决定了它「会不会用、会不会填错参数」 06 ChatUsage token 用量 输入 / 输出 token 统计，算钱用 05 ExecutionConfig 执行配置 超时与重试：模型默认 5 分钟 / 3 次，工具默认 5 分钟 / 1 次 05 fallbackModel 备用模型 主模型挂了切过去；两套 key 都要在环境变量里 05"},{"p":"appendix/glossary.html","n":"A 术语表：中英对照 + 一句话直觉","s":"tool","t":"工具系统","x":"术语 中文 一句话直觉 章 Toolkit ★ 工具集 注册表 + schema 生成 + 执行入口； registerTool 收对象， getToolNames 能自查 06 @Tool 工具注解 把普通方法变成工具；常用属性 name / description / readOnly / returnDirect 06 @ToolParam 参数注解 描述一个参数： name / description / required （默认 true） 06 ToolGroup 工具分组 按组激活：一次只把用得上的工具发给模型，省 token 也少误调 06 ToolExecutor 工具执行器 真正反射调用方法、把返回值转成 ToolResultBlock 的那层 06 ToolSuspendException 工具挂起 工具主动说「我还没完，等我」；对应 TOOL_SUSPENDED 06 returnDirect 直接返回 工具结果直接作为最终回答，不再回模型加工 06 AgentTool Agent 即工具 把一个 agent 暴露成工具给另一个 agent 用，是「agent 协作」最朴素的做法 06 MCP 外部工具协议 Model Context Protocol：工具不在本进程里时，用它接进来 06 @Tool 的 10 个属性： Tool.java:70 ； Toolkit ： Toolkit.java:70"},{"p":"appendix/glossary.html","n":"A 术语表：中英对照 + 一句话直觉","s":"state","t":"状态与记忆","x":"术语 中文 一句话直觉 章 AgentState ★ 智能体状态 一份会话的全部可持久化内容：消息上下文、权限上下文、工具上下文、任务列表…… 07 AgentStateStore ★ 状态存储 按 (userId, sessionId, key) 读写；实现可换文件 / 内存 / Redis / MySQL 07 State 可存状态 能被 store 序列化的标记接口；不是所有对象都能往里塞 07 JsonFileAgentStateStore 文件状态存储 落盘到 <root>/<userId>/<sessionId>/ ，一个 JSON + 一个 JSONL 07 InMemoryAgentStateStore 内存状态存储 进程内 Map，支持 CAS；测试和单次脚本首选 07 saveIfVersion 带版本写入 乐观锁：版本对得上才写，对不上返回 UNVERSIONED 且不写 07 ConflictPolicy 冲突策略 OVERWRITE 后者覆盖 / FAIL 直接失败 / APPEND_MERGE 只追加新消息再重试 07 Memory 短期记忆 「进上下文的那串消息」； StateBackedMemory 把它接到 store 上 07 LongTermMemory 长期记忆 跨会话的检索式记忆， 不是 消息列表；写入与召回都要自己设计 07 LongTermMemoryMode 长期记忆模式 AGENT_CONTROL 模型自己存取 / STATIC_CONTROL 框架按 Hook 存取 / BOTH 两者都要 07 AgentState ： AgentState.java:57 ； AgentStateStore ： AgentStateStore.java:61 ； ConflictPolicy ： ConflictPolicy.java:34 ； LongTermMemoryMode ： LongTermMemoryMode.java:54"},{"p":"appendix/glossary.html","n":"A 术语表：中英对照 + 一句话直觉","s":"permission","t":"权限与 HITL","x":"术语 中文 一句话直觉 章 HITL ★ 人在回路 Human-in-the-loop：执行前停下来等人批，批完接着跑 08 PermissionMode ★ 权限模式 DEFAULT / ACCEPT_EDITS / EXPLORE / BYPASS / DONT_ASK 08 PermissionBehavior ★ 权限动作 ALLOW / DENY / ASK / PASSTHROUGH （交给下层继续判断） 08 PermissionRule 权限规则 四元组：工具名 + 参数模式 + 动作 + 来源标签（如 userSettings / suggested ） 08 PermissionContextState 权限上下文 模式 + 规则表；存在 AgentState 里，所以换 session 就重置 08 PermissionEngine 权限引擎 每次工具调用前算一次决策；规则全落空就走模式的默认行为 08 PermissionDecision 权限决策 引擎的结论：行为 + 给用户看的消息 + 理由 + 可改写的参数 + 建议规则 08 ConfirmResult ★ 确认结果 用户对某次 ASKING 的回答：同意/拒绝 + 理由 + 可顺带加入的规则 08 RequireUserConfirmEvent 请求确认事件 暂停时发出， getToolCalls() 给你要问的那批工具的 原件 11 PERMISSION_ASKING 等待批准 一种 正常 的结束原因，不是异常；下一轮带上 ConfirmResult 再调即可 08 PermissionMode ： PermissionMode.java:33 ； PermissionBehavior ： PermissionBehavior.java:32 ； PermissionEngine ： PermissionEngine.java:47"},{"p":"appendix/glossary.html","n":"A 术语表：中英对照 + 一句话直觉","s":"event","t":"事件、Hook 与中间件","x":"术语 中文 一句话直觉 章 AgentEvent ★ 智能体事件 事件流里的最小单位，多数带 replyId ； AGENT_RESULT 、 REQUEST_STOP 、 CUSTOM 、 ALL_TOOLS_DENIED 、 SUBAGENT_EXPOSED 不带。2.0.4 里有 31 种类型 04 replyId 回复 id 一次调用内所有事件的关联键；并发调用时靠它分组 04 start / delta / end 三段式 文本、思考、数据、工具调用、工具结果都是「开始 → 增量 → 结束」三件套 04 AgentResultEvent 结果事件 生命周期 正常结束 时发，携带最终 Msg ；暂停也算正常结束 11 AgentEndEvent 结束事件 doFinally 里必发，无论是成功、失败还是取消 11 Hook ★ 钩子 在固定切点被回调；能读能改事件，也能 stopAgent() 09 HookEvent 钩子事件 Hook 收到的对象： PreCall / PostReasoning / PreActing …… 与 AgentEvent 不是一套 09 MiddlewareBase 中间件 包住「模型调用 / 推理 / 行动」三段，能替换这一段怎么做，而不只是旁观 09 MiddlewareChain 中间件链 多个中间件的执行顺序；顺序错了，后面的看不到前面的改动 09 stopAgent() 主动叫停 Hook 在某个切点结束本轮，对应 *_STOP_REQUESTED 系列 reason 09 AgentEventType 共 31 个值： AgentEventType.java:40 ； Hook ： Hook.java:122 ； MiddlewareBase ： MiddlewareBase.java:59"},{"p":"appendix/glossary.html","n":"A 术语表：中英对照 + 一句话直觉","s":"harness","t":"Harness 专有名词","x":"这些词只在 agentscope-harness 里出现。第 10 章给过全景，第 12–18 章逐项展开；这里只做名词解释，右侧「章」列可以直接跳到对应小节。 术语 中文 一句话直觉 章 workspace 工作区 文件工具和 Shell 的根目录；不配就落到默认目录 12 filesystem 文件系统抽象 AbstractFilesystem + Local / Remote / Sandbox 三种 spec，决定文件到底存在哪 12 sandbox 沙箱 把 Shell / 文件操作关进受限环境里跑 13 subagent 子智能体 把子任务交给另一个 agent；声明式写法是 SubagentDeclaration 14 skill 技能 可复用的能力包（通常一个 SKILL.md + 资源），按需加载 16 plan mode 计划模式 先产出计划再执行；执行前只放开只读工具 17 compaction 上下文压缩 消息太长时摘要压掉旧内容， CompactionConfig 可调 15 transcript 会话记录 完整流水（含被压缩掉的部分），由 TranscriptStore 负责 15 message bus 消息总线 跨轮次投递：inbox 队列、唤醒队列、会话事件回放 18 gateway 网关 会话键 → 稳定 sessionId ，并保证同一会话串行； HarnessGateway 18 channel 渠道 把平台消息规范化成 InboundMessage ，再把回复投回去 18 DmScope 私聊粒度 决定同一句「你好」在 DM 里落成几个会话；四取一，默认 MAIN 18 turn gate 会话闸门 同一会话同时只跑一轮；本地实现是公平信号量排队 18 inbox 收件箱 后台结果先入队，下一个 reasoning step 开头被排空并注入成 hint 18 async tool 异步工具 工具超过阈值就先回占位结果，后台跑完再回灌；需显式开启 18 wakeup 唤醒 WakeupDispatcher 把闲置会话叫起来跑一轮 18 artifact 产物 agent 生成、需要交付给用户的文件 12"},{"p":"appendix/glossary.html","n":"A 术语表：中英对照 + 一句话直觉","s":"abbrev","t":"缩写与约定","x":"缩写 全称 在这里指什么 SPI Service Provider Interface JDK 的服务发现机制， ModelProvider / AgentStateStore 的扩展都靠它 CAS Compare-And-Swap 乐观锁式的「版本对上才写」，对应 saveIfVersion HITL Human-in-the-loop 执行前暂停、等人批 MCP Model Context Protocol 外部工具/资源的接入协议 RAG Retrieval-Augmented Generation 先检索再回答；core 里有 Knowledge 与检索工具 OTel OpenTelemetry 链路追踪， tracing 包里的 Tracer JSONL JSON Lines 一行一个 JSON；文件状态存储用它追加消息，避免整文件重写 JDK Java Development Kit 2.0.4 的 class 文件是 17，编译目标最低 17"},{"p":"appendix/glossary.html","n":"A 术语表：中英对照 + 一句话直觉","s":"next","t":"下一步","x":"术语混脸熟之后，遇到具体报错去 附录 B 报错速查 ；要查某个 builder 方法去 附录 C API 速查 ；想知道某段逻辑在哪个包，去 附录 D 源码地图 。 背不下来是正常的 这张表的作用是 查 ，不是背。真正需要肌肉记忆的只有八个： Msg 、 ContentBlock 、 ToolUseBlock 、 GenerateReason 、 Toolkit 、 AgentState 、 AgentStateStore 、 ConfirmResult 。其余用到再查。"},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"how","t":"怎么用这一页","x":"先在页面里搜 报错文本的前半句 （比如 Agent is paused for ），别搜整行——里面的 id 每次都不一样 每张卡的结构固定： 你会看到 → 因为 → 改成 。先看「因为」，再看「改成」，否则容易照着改但没改到根因 卡底的「 相关章节 」指向真正讲这件事的小节（带源码行号）；想弄懂机制而不是背结论，顺着点过去 Java 的异常是套娃的： 先看最下面那个 Caused by ，那才是真正的抛出点 表里标 很常见 的是新手第一周几乎一定会撞上的 每张卡右上角的 # 是 这一条自己的链接 ，复制给别人会直接落到这条错上 一个反直觉的前提：很多「报错」其实是正常结束 PERMISSION_ASKING 、 MAX_ITERATIONS 、 TOOL_SUSPENDED 这些 不是异常 ，它们是 GenerateReason 。框架只是把「停下来等你」当成一种正常结果返回， 真正会抛异常的，是你的代码违反了某个约定（id 对不上、状态没配、线程里 block）。"},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"build","t":"构建与启动","x":""},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"hitl","t":"权限与 HITL","x":"这一组的共同点： 它们都在你「第二次调用」的时候才炸 。第一次调用是正常返回的，reason 是 PERMISSION_ASKING ；你没接这个信号，拿同一份状态又调了一次，于是撞上校验。"},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"tool","t":"工具","x":""},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"state","t":"状态与存储","x":""},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"reactor","t":"Reactor 与响应式","x":""},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"model","t":"模型 HTTP 与参数","x":""},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"hook","t":"Hook、中间件与 Harness","x":""},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"debug","t":"三步定位法：表里没有的错怎么办","x":"第一步：先确定它属于「异常」还是「结束原因」 把结果消息的 getGenerateReason() 打出来。是 PERMISSION_ASKING / MAX_ITERATIONS / TOOL_SUSPENDED 就不是 bug，是流程问题；真的是异常，再往下走。 第二步：把事件流打开，看它停在哪一类事件 streamEvents(...).doOnNext(ev -> System.out.println(ev.getType())) ，先看最后一条事件是 MODEL_CALL_* 、 TOOL_* 还是 REQUIRE_USER_CONFIRM 。 停在不同家族，排查方向完全不同（模型/网络 vs 工具/参数 vs 权限）。 第三步：解包 + 最小复现 用 Exceptions.unwrap(e) 找到真正的异常类，再按类名回源码搜 throw new 该类 ，直接看到抛出的那一行和它的判断条件。 然后把上下文缩到「一个工具 + 一句输入 + 内存存储」，能复现就基本定位了。 两个不花钱的调试开关 ① 把日志级别开到 DEBUG ，框架里大量关键分支都有 logger.debug/info （比如工具注册、CAS 冲突、确认恢复）； ② 先换成 InMemoryAgentStateStore 再试——如果换了就不报错，问题几乎一定在「持久化状态和新代码不匹配」上。"},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"next","t":"下一步","x":"报错解决之后，如果想知道某个类到底在哪、为什么这么设计，去 附录 D 源码地图 ； 如果只是忘了某个方法叫什么，去 附录 C API 速查 ； 如果概念本身还没搞清楚，回 附录 A 术语表 。"},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"err-unsupported-class-version","t":"1. 很常见 UnsupportedClassVersionError","x":"1. 很常见 UnsupportedClassVersionError 你会看到 java.lang.UnsupportedClassVersionError: io/agentscope/core/ReActAgent has been compiled by a more recent version of the Java Runtime (class file version 61.0), this version ... recognizes ... 52.0 因为 2.0.4 的 class 文件是 Java 17（61.0），你用的是 Java 8（52.0）或 11（55.0）在跑。 改成 把 maven.compiler.release 设成 17 ，并确认 IDEA 的 Project SDK 和 Run 配置里的 JRE 都是 17+。用 JDK 21 编译、release 定 17 也没问题。 相关章节： 01 环境与依赖 · 陷阱与窍门（JDK 17）","k":"err"},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"err-model-not-found","t":"2. 很常见 Cannot resolve model: \"qwen-plus\"","x":"2. 很常见 Cannot resolve model: \"qwen-plus\" 你会看到 后面还跟着一段 Possible causes: ，列出命名模型、SPI provider、各家扩展模块和环境变量。 因为 模型 id 的格式是 <provider>:<model-name> 。只写 qwen-plus 没有前缀， ModelRegistry 不知道找谁；或者写了前缀但 pom.xml 里没引对应扩展。 改成 补前缀： .model(\"dashscope:qwen-plus\") ；同时确认依赖里有 agentscope-extensions-model-dashscope （OpenAI / Gemini / Anthropic / Ollama 同理，换对应扩展）。 相关章节： 05 模型层 · 一个字符串怎么变成模型对象","k":"err"},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"err-api-key-env","t":"3. Environment variable DASHSCOPE_API_KEY is required to auto-create model: dashscope:qwen-plus","x":"3. Environment variable DASHSCOPE_API_KEY is required to auto-create model: dashscope:qwen-plus 你会看到 构建 agent 或第一次调用时直接抛 IllegalStateException ，不是 HTTP 401。 因为 provider 是用 System.getenv 读的。IDEA 从桌面图标启动时 继承不到 你刚在 PowerShell 里 setx 的变量；改完环境变量不重启 IDE 也读不到。 改成 三条路任选：① 在 IDEA 的 Run Configuration → Environment variables 里显式加；② 完全退出 IDEA 再启动；③ 不走字符串 id，直接 ModelRegistry.register(\"my-model\", 自己 new 的实例) 或 .model(Model) 传实例。 相关章节： 02 第一个 Agent · 第 2 步：设一个 API Key","k":"err"},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"err-model-id-blank","t":"4. IllegalArgumentException: modelId must not be blank","x":"4. IllegalArgumentException: modelId must not be blank 你会看到 构建阶段就失败，堆栈里是 ModelRegistry.resolve 。 因为 .model(\"\") 、 .model(\" \") 会得到 modelId must not be blank ；传 null 则先走 Objects.requireNonNull ，抛 NullPointerException: modelId 。 改成 给一个合法的 id。完全不写 .model(...) 时 build() 仍能成功，但首次 call() 会因 model == null 抛 NPE，所以本质上仍必须给模型。 相关章节： 05 模型层 · 一个字符串怎么变成模型对象","k":"err"},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"err-paused-without-confirm","t":"5. 很常见 一长串 Agent is paused for human-in-the-loop confirmation","x":"5. 很常见 一长串 Agent is paused for human-in-the-loop confirmation 你会看到 java.lang.IllegalStateException: Agent is paused for human-in-the-loop confirmation: the following tool call(s) are in ASKING state and need your approval before the agent can continue: [delete_note (id=call_abc123)]. This call supplied no confirmation, so it cannot proceed. To resume, send a follow-up message that carries a List<ConfirmResult> under the metadata key \"agentscope_confirm_results\", e.g.: UserMessage.builder() .metadata(Map.of(Msg.METADATA_CONFIRM_RESULTS, List.of(new ConfirmResult(true, toolCall)))) .build(); Tip: capture the ToolUseBlocks from the RequireUserConfirmEvent emitted when the agent paused. 因为 上一次调用停在了 ASKING ，而这一次你送进去的消息 没有携带 ConfirmResult 。 常见三种触发：① 用 for 循环无脑重试；② 把 UserMessage(input) 当新输入又发了一遍； ③ 换了个进程/重启后，同一个 (userId, sessionId) 从磁盘读回了「等待中」的状态。 改成 按错误里的提示做：从 RequireUserConfirmEvent.getToolCalls() 拿 原件 ，包成 ConfirmResult 塞进下一条消息的 Msg.METADATA_CONFIRM_RESULTS 。 如果是「上次没答完，这次想重新开始」，清掉该 session 的状态或换 sessionId （第 11 章的 /new 就是干这个的）。 相关章节： 08 权限与人机交互 · 事件流版本 · 11 综合案例 · PERMISSION_ASKING 是结局","k":"err"},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"err-confirm-id-mismatch","t":"6. ConfirmResult references non-ASKING tool call ID: xxx. Expected: [yyy]","x":"6. ConfirmResult references non-ASKING tool call ID: xxx. Expected: [yyy] 你会看到 后半句的 Expected 里列出当前真正挂起的 id，通常只有一个，且和你传的不一样。 因为 恢复是靠 id 精确匹配的。你很可能 新造了一个 ToolUseBlock （工具名、参数都一样也没用），或者手里拿的是上一次会话留下的旧 id。 改成 只用事件或结果消息里筛出来的 ASKING 原件。要改参数，用 ToolUseBlock.builder().id(原 id).name(...).input(新参数).build() 重建并保留 id。 相关章节： 11 综合案例 · ConfirmResult 必须拿原件 · 08 · ConfirmResult 的四个字段","k":"err"},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"err-confirm-duplicate","t":"7. Duplicate ConfirmResult for tool call ID: xxx / ConfirmResult.toolCall.id must not be empty.","x":"7. Duplicate ConfirmResult for tool call ID: xxx / ConfirmResult.toolCall.id must not be empty. 你会看到 同一个 id 被回传了两次，或者 id 是空串。 因为 前者常常是把「结果消息里的 ASKING 工具」和「事件里的工具」 合在一起 传了； 后者是自己 new ToolUseBlock(...) 时没填 id。 改成 每个挂起的 id 只回一条 ConfirmResult ；去重后再发。 相关章节： 08 权限与人机交互 · ConfirmResult 的四个字段","k":"err"},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"err-pending-tool-results","t":"8. Pending tool calls exist without results. Enable enablePendingToolRecovery or provide tool results. Pending IDs: [...]","x":"8. Pending tool calls exist without results. Enable enablePendingToolRecovery or provide tool results. Pending IDs: [...] 你会看到 没有 ASKING 字样，只有 pending id。 因为 这是「外部工具」那条路：模型调了 externalTool = true 的工具（或 SchemaOnlyTool ）， 框架不执行、把调用挂起，等你自己跑完再回填；而你把 enablePendingToolRecovery 关掉了。 改成 要么打开 pending 恢复，要么按 RequireExternalExecutionEvent 的约定把 ExternalExecutionResult 回填进去。别在「外部工具」状态下手动再发一条普通用户消息。 相关章节： 10 两种入口 · 陷阱 3：中断后同 session 重试","k":"err"},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"err-reject-retry-loop","t":"9. 被拒绝后模型反复重试","x":"9. 被拒绝后模型反复重试 你会看到 你回了 n ，模型换个说法又调一次 delete_note ，来回好几轮。 因为 拒绝时没写 reason ，模型只看到默认文案「Permission denied by user」，不知道你是误操作还是永久禁止， 只能换个说法再试一次。顺带纠正一个常见误解： stopOnReject 在 2.0.4 里只被赋进 ReactConfig ， 主循环 没有任何读取点 ，写了也不会「一拒就停」。 改成 用 new ConfirmResult(false, call, null, \"用户拒绝，请不要重试\") 把意图写清楚； 真要「全拒就停」，用中间件： onActing 里识别 AllToolsDeniedEvent ，再在流尾接一个 RequestStopEvent （第 09 章的「我想…」表里就是这一行）。 相关章节： 08 · 拒绝之后模型看到什么 · stopOnReject 设了没人读","k":"err"},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"err-tool-not-found","t":"10. IllegalArgumentException: Tool not found: xxx （自己抛的）","x":"10. IllegalArgumentException: Tool not found: xxx （自己抛的） 你会看到 堆栈指向 Toolkit.addToolToGroup 或 Toolkit.updateToolPresetParameters 。 因为 这是 配置错误 ，不是模型乱调工具：你往一个分组里加工具、或改预设参数时，那个工具还没注册 / 名字拼错。 改成 先 toolkit.getToolNames() 把真实名字打出来核对。工具名以 @Tool(name = \"...\") 为准，没写 name 才用方法名。 相关章节： 06 工具系统 · 建组、归组、开 meta tool","k":"err"},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"err-tool-not-found-by-model","t":"11. 很常见 模型调了一个不存在的工具","x":"11. 很常见 模型调了一个不存在的工具 你会看到 事件流里出现 [tool] get_weather -> ERROR ，结果内容是第一行 Tool not found: get_weather 。 不会抛异常。 因为 框架把它当成一次「工具执行失败」写回上下文，让模型有机会换方案。真正的根因通常是：工具没注册、被工具分组隐藏了、或者名字和 schema 不一致。 改成 对照 getToolNames() 和当前激活的分组（ getActiveGroups() ）。注意： 同名工具后注册的会静默覆盖前面的 ，不报错——两个类都写了 @Tool(name = \"search\") 时，只有一个生效。 相关章节： 06 工具系统 · 一次工具调用的 9 件事","k":"err"},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"err-tool-converter","t":"12. IllegalStateException: Failed to create converter from @Tool annotation","x":"12. IllegalStateException: Failed to create converter from @Tool annotation 你会看到 堆栈里带着 Caused by ，通常指向你的方法签名。 因为 返回值类型没有可用的转换器：传了泛型擦除后信息不全的类型、返回了一个既不是 String 也不是可序列化 POJO 的对象，或者参数类型不支持生成 JSON Schema。 改成 先用 String 返回人话（这也是第 11 章 NotesTools 的做法），确实要结构化就返回简单 POJO / Map 。 相关章节： 06 工具系统 · 返回值怎么变成 ToolResultBlock","k":"err"},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"err-tool-invocation-wrapped","t":"13. 工具抛异常，模型收到一串 InvocationTargetException","x":"13. 工具抛异常，模型收到一串 InvocationTargetException 你会看到 ToolResultState.ERROR ，结果文本是 Tool execution failed: <cause message> ； 框架会解包 InvocationTargetException ，通常不含反射类名。 因为 工具方法声明了 throws 并真的抛了受检异常，框架用反射调用后包装了一层。 改成 在工具内部 try/catch ，把失败翻译成一句人和模型都能懂的话返回： return \"写入失败：\" + e.getMessage(); 。这样模型还有机会换方案。 相关章节： 06 工具系统 · 兜底：异常变 error 结果","k":"err"},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"err-session-id-blank","t":"14. IllegalArgumentException: sessionId must not be blank","x":"14. IllegalArgumentException: sessionId must not be blank 你会看到 堆栈指向 JsonFileAgentStateStore 或 InMemoryAgentStateStore 。 因为 调用时既没给 RuntimeContext 的 sessionId ，builder 里也没配 defaultSessionId ； 此时会回退到 name ，再回退到 \"ReActAgent\" ，通常不会空白。只有显式 name(\"\") 或直接调 getAgentState(userId, null) 这类路径才会触发。 改成 给一个稳定的 id： RuntimeContext.builder().userId(\"local\").sessionId(\"cli\").build() ， 或者在 builder 上 .defaultSessionId(\"cli\") 。 相关章节： 07 记忆与上下文 · 不传 sessionId 会怎样 · 02 · RuntimeContext 与 sessionId","k":"err"},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"err-session-conflict","t":"15. ConcurrentSessionModificationException: Concurrent modification of session state (userId=..., sessionId=..., key=agent_state, expectedVersion=...)","x":"15. ConcurrentSessionModificationException: Concurrent modification of session state (userId=..., sessionId=..., key=agent_state, expectedVersion=...) 你会看到 另一个副本/进程刚好也在写同一个会话，其中一个成功，另一个拿到这个异常。 因为 你把 conflictPolicy 设成了 FAIL ，而乐观锁版本对不上。 APPEND_MERGE 也可能在合并重试后失败。 改成 先问自己「同一个 session 会不会被两个实例同时写」。会：要么在网关层按 session 粘性路由，要么接受 OVERWRITE （后写覆盖）， 要么用 APPEND_MERGE 并确保压缩/摘要轮次不走这条路——它 不适合会重写历史的轮次 。 相关章节： 07 记忆与上下文 · 并发与隔离（ConflictPolicy）","k":"err"},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"err-forget-on-restart","t":"16. 不报错，但「重启就失忆」","x":"16. 不报错，但「重启就失忆」 你会看到 进程内聊得很好，重启后模型完全不记得刚才说过什么。没有任何异常。 因为 两种情况：① 没配 stateStore ，状态只在内存；② 每次都新建不同的 sessionId （比如拿时间戳当 id）， 每次都是新会话。 改成 配 JsonFileAgentStateStore （或 Redis / MySQL），并把 (userId, sessionId) 固定下来。 验证方法：退出重进，问「我刚才让你记了什么」。 相关章节： 07 记忆与上下文 · 一次 call 从加载到落盘","k":"err"},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"err-state-dir-base64","t":"17. 状态目录里出现看不懂的目录名","x":"17. 状态目录里出现看不懂的目录名 你会看到 state/5L2g5aW9/... 这样的路径，而不是你的 userId 原文。 因为 JsonFileAgentStateStore 会把带特殊字符的 userId / sessionId 做 Base64-URL 安全编码， 避免路径穿越和非法字符。 改成 不用改。想肉眼可读就用纯 ASCII 的 id； ~/.notes-agent/state/local/cli/ 这种就能原样保留。 相关章节： 07 记忆与上下文 · 目录布局与 Base64 编码","k":"err"},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"err-block-in-reactor-thread","t":"18. 很常见 block()/blockFirst()/blockLast() are blocking, which is not supported in thread reactor-http-nio-2","x":"18. 很常见 block()/blockFirst()/blockLast() are blocking, which is not supported in thread reactor-http-nio-2 你会看到 一到 .block() 或 .blockLast() 就炸，堆栈里全是 Reactor 的调度器。 因为 你正跑在 Reactor 的 非阻塞线程 上（WebFlux controller、SSE handler、某个 publishOn 之后）， 而 block 会占住这个只能容纳少量线程的线程池。 改成 ① 返回 Mono / Flux 让框架订阅，不要在中间 block；② 真必须同步，就 .subscribeOn(Schedulers.boundedElastic()) 挪到弹性线程池；③ 命令行程序里在 main 线程 block 是安全的。 相关章节： 03 响应式必修 · 陷阱 2：doOnNext 里 block()","k":"err"},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"err-model-observe-timeout","t":"19. TimeoutException: Did not observe any item or terminal signal within 300000ms","x":"19. TimeoutException: Did not observe any item or terminal signal within 300000ms 你会看到 一次调用卡 5 分钟后失败，共 3 次尝试（1 次首发 + 2 次重试）还是一样。 因为 模型默认的 ExecutionConfig 是「5 分钟超时 + 3 次尝试」，工具是「5 分钟 + 1 次」。超时被算作可重试错误，所以你会看到三次。 改成 长回答 / 慢模型用 .modelExecutionConfig(ExecutionConfig.builder().timeout(Duration.ofMinutes(2)).maxAttempts(2).build()) 明确写出来； 先确认不是网络代理拦住了请求。 相关章节： 05 模型层 · 重试与降级（5 分钟超时）","k":"err"},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"err-reactive-wrapped","t":"20. 异常被包成 reactor.core.Exceptions$ReactiveException","x":"20. 异常被包成 reactor.core.Exceptions$ReactiveException 你会看到 真正的错误信息躲在 getCause() 里，日志看起来像框架乱抛。 因为 Reactor 会把回调里的受检异常包装一层再往下传。 改成 用 reactor.core.Exceptions.unwrap(e) 拆开再判断类型；打印日志时打 unwrap 之后的结果。 相关章节： 03 响应式必修 · 陷阱与窍门（异常处理）","k":"err"},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"err-cold-stream","t":"21. 什么都没发生：不报错、也不输出","x":"21. 什么都没发生：不报错、也不输出 你会看到 agent.call(\"...\") 这一行执行完了，但模型没被调用。 因为 Mono / Flux 是 冷流 ：不订阅就不执行。忘记 .block() 、 .subscribe() 或返回给框架，就什么都不会发生。 改成 同步场景 .block() ；异步场景 .subscribe(...) 并把返回的 Disposable 管好；Web 场景直接返回 Mono 。 相关章节： 03 响应式必修 · 冷流不订阅就不执行","k":"err"},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"err-http-401","t":"22. HTTP 401 / AuthenticationException","x":"22. HTTP 401 / AuthenticationException 你会看到 消息里带 401 和响应体片段，例如 Incorrect API key provided 。 因为 key 错、过期，或者读的是另一个环境变量名（OpenAI 是 OPENAI_API_KEY ，DashScope 是 DASHSCOPE_API_KEY ）。 改成 换 key 后 重启进程 ；别把 key 写进代码或提交到仓库。 相关章节： 02 第一个 Agent · 设一个 API Key","k":"err"},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"err-http-429","t":"23. HTTP 429 或 5xx","x":"23. HTTP 429 或 5xx 你会看到 共 3 次尝试（1 次首发 + 2 次重试）后失败，错误里带状态码；日志里能看到退避间隔从 2 秒涨到 30 秒。 因为 限流或服务端抖动，都属于 可重试 错误。 改成 降并发、加长 maxBackoff ，或者换 fallbackModel 。别把 maxAttempts 调到很大——重试也是有成本的。 相关章节： 05 模型层 · 哪些错误才会重试","k":"err"},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"err-http-400-tools","t":"24. HTTP 400：模型不支持 tools / response_format","x":"24. HTTP 400：模型不支持 tools / response_format 你会看到 400 ，消息里提到 tools 、 tool_choice 或 response_format 不支持。 因为 你用的模型不支持工具调用，或 provider 不支持原生结构化输出。结构化输出会先试原生路径，失败后回退到「合成工具」路径——但工具本身不支持就没救了。 改成 换支持 tools 的模型；结构化输出遇到这类 400 时，框架已经会自动回退，不要去手动关掉。 相关章节： 05 模型层 · 结构化输出与合成工具回退","k":"err"},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"err-hook-system-inject","t":"25. Hooks must not inject SYSTEM messages into PreCallEvent.inputMessages. Use event.setSystemMessage() ...","x":"25. Hooks must not inject SYSTEM messages into PreCallEvent.inputMessages. Use event.setSystemMessage() ... 你会看到 在 onEvent(PreCallEvent) 里往消息列表塞了 SystemMessage 之后抛这个。 因为 消息列表的「尾巴」会被持久化进记忆，SYSTEM 消息一旦进去就会越积越多。 改成 改用 event.setSystemMessage(...) 或 event.appendSystemContent(...) ，让框架把它放在正确的位置。 相关章节： 09 Middleware 与 Hook · Hook 整包废弃","k":"err"},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"err-null-message","t":"26. Agent returned null message","x":"26. Agent returned null message 你会看到 调用结束时报这个错，堆栈在 AgentBase.notifyPostCall 。 因为 某个 Hook 在 PostCallEvent 里把最终消息改成了 null，或者你的 doCall 返回了空流。 改成 Hook 里只做「修改」不做「清空」；自定义 agent 时确保最终有一个 Msg 。 相关章节： 09 Middleware 与 Hook · PostCall 能改最终 Msg","k":"err"},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"err-workspace-blank","t":"27. IllegalArgumentException: workspace path must not be blank （Harness）","x":"27. IllegalArgumentException: workspace path must not be blank （Harness） 你会看到 构建 HarnessAgent 时抛，指向 HarnessAgent.Builder.workspace 。 因为 .workspace(\"\") 或 .workspace(\" \") 。 改成 给一个真实目录，优先绝对路径： .workspace(home.resolve(\"workspace\")) 。相对路径会按进程工作目录解析，IDEA 里和命令行里可能不是同一个地方。 相关章节： 12 工作区与文件系统 · workspace 不能空白","k":"err"},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"err-max-iters-retries","t":"28. IllegalArgumentException: maxIters must be > 0 / maxRetries must be > 0","x":"28. IllegalArgumentException: maxIters must be > 0 / maxRetries must be > 0 你会看到 构建阶段直接失败，不用等到调用。 因为 把上层配置（比如 yml 里的 0 或负数）原样传了进来。 改成 做一次兜底： Math.max(1, configured) ；同时检查是不是把「不限制」误写成了 0——框架里没有「0 表示无限」的约定。 相关章节： 10 两种入口 · 触顶：多调一次模型写总结 · 05 模型层 · maxRetries 不是「重试 3 次」","k":"err"},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"err-gateway-no-agent","t":"29. IllegalStateException: At least one agent must be registered via agent(...)","x":"29. IllegalStateException: At least one agent must be registered via agent(...) 你会看到 GatewayBootstrap.builder().build() 时直接抛，堆栈停在 build() 。 因为 只写了 .channel(...) 或 .distributedStore(...) ，一个 agent 都没注册。 改成 至少加一个 .agent(\"main\", agent) （或 lambda 版 .agent(\"main\", b -> ...) ）。 相关章节： 18 网关、渠道与异步 · GatewayBootstrap 装配","k":"err"},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"err-main-agent-missing","t":"30. IllegalStateException: mainAgent('sales') not found in registered agents","x":"30. IllegalStateException: mainAgent('sales') not found in registered agents 你会看到 同上，在 build() 阶段抛出，括号里就是你写的那串名字。 因为 .mainAgent(\"sales\") 用的是注册时的 key （ agent(String, ...) 的第一个参数），而注册表里没有这个 key。 改成 核对 key 的拼写与大小写—— agent(...) 只有「key + 实例」与「key + lambda」两种重载，没有单参实例版；不写 .mainAgent(...) 时取第一个注册的（按插入顺序），不会报错但可能指错 agent。 相关章节： 18 网关、渠道与异步 · mainAgent 的 key","k":"err"},{"p":"appendix/errors.html","n":"B 报错速查：看到什么错，改什么地方","s":"err-chatui-no-gateway","t":"31. IllegalStateException: ChatUiChannel has no gateway. Use GatewayBootstrap.chatUiChannel(), or construct with ChatUiChannel.create(gateway).","x":"31. IllegalStateException: ChatUiChannel has no gateway. Use GatewayBootstrap.chatUiChannel(), or construct with ChatUiChannel.create(gateway). 你会看到 调 send(...) / sendToSubagent(...) 时抛，而构造对象本身不报错。 因为 ChatUiChannel 的 gateway 字段必须由外部注入； resolveGateway() 发现为 null 就抛。 改成 走 gw.chatUiChannel(config) 或 ChatUiChannel.create(gateway) ；单 agent 场景直接用 agent.channel(ChatUiChannel.perPeer()) 。 相关章节： 18 网关、渠道与异步 · ChatUiChannel 两种发送姿势","k":"err"},{"p":"appendix/api-cheatsheet.html","n":"C API 速查：Builder 方法按能力分组","s":"how","t":"怎么用这一页","x":"先看共有组 ：28 个名字覆盖了 90% 的日常配置，学会这些就能写出第 11 章那种工程 所有方法都返回 this ，可以链式调用； 校验大多发生在 build() 或首次调用 ，不是设置的那一刻 表里的「默认」只写框架自己的默认值；你写了就以你为准 两个数字可以自己数：在类文件里搜 public Builder 。数出来 ReActAgent 43、 HarnessAgent 97（含重载） 一个数字对不上的地方：43 + 66 ≠ 97 的直觉 因为重载算了多次。按「名字」去重后： 共有 28 个名字 （31 个方法签名）， core 独有 12 个 ， Harness 独有 58 个 。28 + 58 = 86 个名字， 再加上 model 、 fallbackModel 、 workspace 、 filesystem 等重载，正好凑成 97。 core 的 builder： ReActAgent.java:4888 ；Harness 的 builder： HarnessAgent.java:1506"},{"p":"appendix/api-cheatsheet.html","n":"C API 速查：Builder 方法按能力分组","s":"shared","t":"两边都有：28 个名字（31 个签名）","x":"方法 作用 默认 / 注意 name(String) agent 的名字，出现在事件、日志、Harness 的状态目录里 不设会得到类名派生的默认值 description(String) 给「别人」看的描述：当这个 agent 被包成工具或子 agent 时用得上 随便写也能跑，但多 agent 场景会误导对方 sysPrompt(String) 系统提示词；Harness 里还会拼上工作区上下文 支持文本块； null 等于不设 checkRunning(boolean) 历史开关，2.0.4 里只被保存和转发 不再做并发门禁 ；同 session 并发是排队，见第 10 章 model(String) / model(Model) 模型 id 或实例 id 走 ModelRegistry 解析；不设 model 时 build() 仍能成功，首次 call() 会 NPE toolkit(Toolkit) 工具集 Harness 会在你这份之上再挂内置工具 maxIters(int) 一轮对话最多几次「推理 → 行动」 默认 10；触顶不是异常，是多调一次模型写摘要 generateOptions(GenerateOptions) 温度、topP、maxTokens、responseFormat 模型 id 本身不带参数，参数全在这里 modelExecutionConfig(ExecutionConfig) 模型调用的超时与重试 默认 5 分钟 / 3 次，退避 2s → 30s toolExecutionConfig(ExecutionConfig) 工具执行的超时与重试 默认 5 分钟 / 1 次（工具重试有副作用风险） toolExecutionContext(ToolExecutionContext) 把自定义 POJO 按类型注入工具方法 已废弃 ，改用 RuntimeContext 携带 hook(Hook) / hooks(List<Hook>) 注册切点回调 按优先级排序后执行；可叠加 middleware(MiddlewareBase) / middlewares(...) 注册中间件，包住模型调用 / 推理 / 行动 顺序敏感：后面的看不到前面改之前的样子 enableMetaTool(boolean) 注册 reset_equipped_tools ，让模型自己切换工具分组 默认关；工具很多时才值得开 enableTaskList() / enableTaskList(boolean) 打开内置任务清单工具，让模型自己拆 TODO 默认关；长任务效果好，短问答是噪音 enablePendingToolRecovery(boolean) 允许恢复「挂起的工具调用」 用外部工具时几乎必须开 stateStore(AgentStateStore) 状态存储 core 不设=只在内存；Harness 不设=默认文件存储 defaultSessionId(String) 没给 RuntimeContext 时用的会话 id 两侧都没给，存储会抛 sessionId must not be blank maxRetries(int) 模型调用最大尝试次数（含首次） 默认取 ModelConfig.DEFAULT_MAX_RETRIES ；必须 > 0 fallbackModel(Model) / fallbackModel(String) 主模型失败时切换 两套 key 都要在；收到首个错误信号即切换，不区分 4xx/5xx/超时 failoverListener(FailoverListener) 监听「切到备用模型」这件事 打日志、告警用 stopOnReject(boolean) 这一轮工具全被拒时是否直接停 2.0.4 未接线，设置后不会生效；需用中间件监听 AllToolsDeniedEvent permissionContext(PermissionContextState) 权限模式 + 规则表 不设= @Tool 默认 PASSTHROUGH ，危险工具会直接跑 skillRepository(AgentSkillRepository) / skillRepositories(...) 技能仓库 core 也能用技能，只是没有 Harness 那套默认目录 skillFilter(SkillFilter) 过滤可见技能 按技能名筛，没有标签过滤"},{"p":"appendix/api-cheatsheet.html","n":"C API 速查：Builder 方法按能力分组","s":"react","t":"只有 ReActAgent 有：12 个","x":"这 12 个都在解决两件事： 长期记忆 / RAG 和 会话状态冲突 。Harness 走了另一套（ memory(...) 与分布式存储），所以没有转发这些。 方法 作用 默认 / 注意 conflictPolicy(ConflictPolicy) 多副本写同一会话时的策略 OVERWRITE / FAIL / APPEND_MERGE longTermMemory(LongTermMemory) 接入长期记忆实现 不接就只有上下文里的短期记忆 longTermMemoryMode(LongTermMemoryMode) 谁来决定存取 AGENT_CONTROL / STATIC_CONTROL / BOTH longTermMemoryAsyncRecord(boolean) 写入长期记忆是否异步 异步快，但失败不会阻塞主流程，也不好发现 knowledge(Knowledge) / knowledges(List) 挂知识库（RAG） 会配合检索工具/hook 使用 ragMode(RAGMode) 检索模式：每次自动检索 / 交给模型决定 自动检索稳，但每轮都花 token retrieveConfig(RetrieveConfig) 召回条数与分数阈值 阈值必须 0.0–1.0，条数必须为正 skillBox(SkillBox) 更细的技能容器（按需加载/执行） 比 skillRepository 更重，先不用 dynamicSkillsEnabled(boolean) 允许运行时动态加载技能 默认开启 skillCodeExecutionEnabled(boolean) 允许技能里执行代码 默认关；开了就要认真配权限 skillWorkDir(Path) 技能的工作目录 相对路径按进程 cwd 解析，建议绝对路径"},{"p":"appendix/api-cheatsheet.html","n":"C API 速查：Builder 方法按能力分组","s":"h-identity","t":"Harness 独有 ①：身份、工作区与可观测","x":"方法 作用 默认 / 注意 agentId(String) Harness 的身份 id：文件系统命名空间与默认状态目录都用它 不设则退回 name ；默认状态在 ~/.agentscope/state/<agentId>/ workspace(Path) / workspace(String) 文件与 Shell 工具的根目录 空白字符串直接抛异常；相对路径按 cwd 解析 environmentMemory(String) 注入「环境记忆」文本：项目背景、约定 会进提示词，别塞太长 additionalContextFile(String) 额外读取一个上下文文件（相对工作区） 适合 AGENTS.md 这类约定文件 maxContextTokens(int) 工作区上下文（AGENTS.md、环境记忆等）注入时的 token 上限 默认 8000 ； 不是 压缩开关，压缩看的是模型上下文窗口 useLegacyXmlWorkspaceContext(boolean) 用旧版 XML 形式拼工作区上下文 兼容老提示词，新项目别开 environment(String) 环境标签 默认 \"prod\" ；技能/权限可能按它分支 artifactDeliveryTarget(ArtifactDeliveryTarget) 注册 deliver_artifact 工具，把产物送出沙箱 / 工作区 不设就不注册；只给主 agent， disableFilesystemTools 时也不注册 enableAgentTracingLog(boolean) 开关 AgentTraceMiddleware （agent 级链路日志） 默认开 ；嫌日志吵才关"},{"p":"appendix/api-cheatsheet.html","n":"C API 速查：Builder 方法按能力分组","s":"h-fs","t":"Harness 独有 ②：文件系统与沙箱","x":"方法 作用 默认 / 注意 abstractFilesystem(AbstractFilesystem) 直接给一个文件系统实现 最灵活，也最需要自己保证线程安全 filesystem(LocalFilesystemSpec) 本地目录文件系统 最常用；根目录就是 workspace filesystem(SandboxFilesystemSpec) 沙箱文件系统 不能逃逸到宿主目录 filesystem(RemoteFilesystemSpec) 远程文件系统 网络 IO，延迟要算进工具超时 filesystemRoute(String, AbstractFilesystem) 按路径前缀分流到不同文件系统 例如 /shared 走远程、其余走本地 disableFilesystemTools() 不挂内置文件工具 只读场景常用 disableShellTool() 不挂 Shell 工具 生产环境默认建议关 disableWebTools() 不挂联网工具 内网/离线部署 webHttpClient(HttpClient) 自定义联网工具用的 HTTP 客户端 需要代理/证书时用"},{"p":"appendix/api-cheatsheet.html","n":"C API 速查：Builder 方法按能力分组","s":"h-context","t":"Harness 独有 ③：上下文、压缩与记忆","x":"这一组是 Harness 和 core 差距最大的地方。core 只给你一个 maxIters ；Harness 把 「上下文总会满」当常态，默认就装了压缩、工具结果驱逐、长期记忆三条管线，还各留了一个 disableXxx() 。 方法 作用 默认 / 注意 compaction(CompactionConfig) 覆盖上下文压缩（分段摘要）配置 默认开启 ，按模型上下文窗口动态触发；传 null 等于关 disableCompaction() 彻底关掉 CompactionMiddleware 长会话慎用：省了摘要调用，但会直接撞模型上限 memory(MemoryConfig) 长期记忆管线：flush + 后台 consolidation + 维护 不设用 MemoryConfig.defaults() ；和压缩是两件事 toolResultEviction(ToolResultEvictionConfig) 超长工具结果挪出上下文、只留占位和指针 默认开，约 8 万字符触发 disableToolResultEviction() 关掉工具结果驱逐 关了以后全靠压缩兜底，一次大输出就可能顶满 disableTranscript() 关掉独立的会话转录（transcript）中间件 javadoc 建议保留；它和 memory hooks 相互独立 transcriptStore(TranscriptStore) 自定义分段追加存储 默认 filesystem 非空时走 ObjectStoreTranscriptStore ，键为 <tenant>/<agentId>/<sessionId>/events/*.jsonl transcriptTenant(String) transcript 对象 key 里的租户段 默认 \"default\" ；多租户共用一个存储桶时必改 disableSessionPersistence() 2.0 起是 空操作 会话持久化已由 ReActAgent 自己管；写它不会有任何效果 disableWorkspaceContext() 不注入工作区上下文（AGENTS.md 等） 关了就只剩你手写的 sysPrompt disableAtPathExpansion() 不展开消息里的 @path 引用 默认展开：按活动文件系统读文件，在消息末尾附 <attached_file> disableMemoryTools() 不注册 memory_search / memory_get / memory_save / session_search 不想让模型自己翻记忆时关 disableMemoryHooks() 停掉记忆 flush 与后台 consolidation 再叠加 disableMemoryTools() 时，连 MEMORY.md 都不注入 压缩与记忆： HarnessAgent.java:1867 ；几个 disable 开关： HarnessAgent.java:2227"},{"p":"appendix/api-cheatsheet.html","n":"C API 速查：Builder 方法按能力分组","s":"h-tools","t":"Harness 独有 ④：工具面与外部接入","x":"这一组的关键词是「接进来」和「派出去」：MCP、外部 schema、子 agent、消息总线、分布式存储。 注意 messageBus 一开，会顺带注册 wait_async_results 工具，工具面就变了。 方法 作用 默认 / 注意 toolsConfig(ToolsConfig) 用代码覆盖 workspace/tools.json 不想让用户改文件时用 disableToolsConfig() 完全不读 tools.json 配置只留在代码里，部署更可预期 registerExternalSchemas(List<ToolSchema>) 注册「只有 schema」的外部工具，调用时挂起等外部 worker 执行 self_hosted 环境用；不执行也不报错，结果是挂起 mcpServerRegistrationListener(...) 监听构建期 MCP server 的注册结果（成功/失败） 不会传给动态创建的子 agent；传 null 关闭投递 subagent(SubagentDeclaration) / subagents(List) 声明子 agent（名字、描述、模型、工具范围） 声明式最稳；描述写不好，编排者就选错人 subagentFactory(name, factory) / (name, description, factory) 用工厂函数完全自定义子 agent 工厂收到的是子 agent 自己的名字（不是任务文本）；description 为空则退回 name disableSubagents() 不装子 agent 中间件 连预声明的也不可用；叶子 agent 常用 disableDynamicSubagents() 禁止运行时动态创建，只保留预声明 想控住「模型自己拉人」就开 externalSubagentTool(Object) 注入外部子 agent 工具（典型是 SessionsTool ） 给「子 agent 不在本进程」的场景 asyncToolTimeout(Duration) 超时工具转后台执行，结果从收件箱回来 必须先设 messageBus ，否则不生效 asyncToolRegistry(AsyncToolRegistry) 跟踪异步工具执行，检测并清理僵死任务 不设就跳过生命周期跟踪 messageBus(MessageBus) 注册 InboxMiddleware ：每次推理前收件箱 同时注册 wait_async_results ；跨进程投递的基础 taskRepository(TaskRepository) 后台子 agent 的任务仓库 要把「跑了多久、结果在哪」查出来就设它 modelResolver(Function<String, Model>) 把子 agent 写的模型名解析成实例 可选；缺省走 ModelRegistry.resolve ，解析失败回退父模型 distributedStore(DistributedStore) 一次给齐状态存储、Base Store、沙箱快照、执行守卫 显式的 stateStore() / filesystem() 优先于它 子 agent 与消息总线： HarnessAgent.java:1933 ； distributedStore 的优先级说明： HarnessAgent.java:1649"},{"p":"appendix/api-cheatsheet.html","n":"C API 速查：Builder 方法按能力分组","s":"h-skill","t":"Harness 独有 ⑤：技能治理","x":"技能有「四层来源」：市场仓库、工作区目录、项目级目录、默认工作区仓库。这几个方法决定哪几层生效、 谁能改、改完怎么晋升。 只记住一个顺序 ： skillsEnabled 负责总闸， enableSkills / disableSkills 是在总闸之上换一个过滤器。 方法 作用 默认 / 注意 projectGlobalSkillsDir(Path) 项目级技能目录，优先级最低 和 skillRepository 叠加，不替换 disableDynamicSkills() 禁止每次调用从工作区动态加载技能 技能改了要重启才生效，换来的是稳定 disableDefaultWorkspaceSkills() 跳过默认的 Layer-4 工作区仓库 只少这一层；自定义仓库和 Layer-3 目录仍在 enableSkillManageTool(SkillManageConfig) / (boolean autoPromote) 给 agent skill_manage 工具，可建/改/归档自己的技能 会把工作区仓库升级成可写变体；参数是「是否自动晋升」 enableSkillPromotionGate(gate, visibilityFilter) 技能晋升门禁 + 可见性过滤链 团队共用技能库时的治理点 enableSkillCurator(SkillCuratorConfig) 后台技能整理（去重、合并、淘汰） 依赖 enableSkillManageTool skillsEnabled(boolean) 总闸：等价 SkillFilter.all() / none() 它写的是同一个 skillFilter 字段 enableSkills(String...) 只留指定名字的技能 等价 SkillFilter.only(...) ；后调用的会覆盖前面的 filter disableSkills(String...) 排除指定名字的技能 等价 SkillFilter.except(...) ；同样会覆盖 技能仓库与目录： HarnessAgent.java:1742 ；技能开关： HarnessAgent.java:2104"},{"p":"appendix/api-cheatsheet.html","n":"C API 速查：Builder 方法按能力分组","s":"h-plan","t":"Harness 独有 ⑥：计划模式与团队","x":"方法 作用 默认 / 注意 enablePlanMode() / enablePlanMode(boolean) 只读设计阶段： plan_enter / plan_write / plan_exit + 只读强制 默认关；开了以后写文件类工具会被拦 planFileDirectory(String) 计划文件放在哪 空白字符串直接忽略 allowShellInPlanMode() / (boolean) 计划模式下允许 shell 默认 禁止 （shell 是双用途，按名字判不出只读）；开了也要求只读用法 teamsMode(TeamClient, TeamContext) / (..., String sessionId) 挂 TeamsMiddleware 和按角色裁剪的 team 工具 三参版把控制面 TeamEvents 绑到指定 session，否则收不到 计划模式： HarnessAgent.java:2161 ；团队模式： HarnessAgent.java:1304"},{"p":"appendix/api-cheatsheet.html","n":"C API 速查：Builder 方法按能力分组","s":"h-gateway","t":"Harness 独有 ⑦：网关、渠道与异步","x":"这一组不是「多一个功能」，而是「把 agent 装成服务」：前四个决定消息怎么进来、结果怎么回来，最后一个 （ channel ）是实例方法，不在 builder 上。 方法 作用 默认 / 注意 messageBus(MessageBus) 跨轮次投递底座：注册 InboxMiddleware （每个 reasoning step 开头排水）、注册 wait_async_results 工具，并给 teams / 子 agent 接线 不写也会自动造 WorkspaceMessageBus(filesystem, \".agentscope/bus\") ，因为 filesystem 默认非 null → inbox 实际总开着 asyncToolTimeout(Duration) 开启异步工具：工具超过时限先回占位结果，后台跑完再回灌 默认 关 ；必须同时有 messageBus，否则整块不装 asyncToolRegistry(AsyncToolRegistry) 异步任务登记表，供 InboxMiddleware 做 stale 检测 不写会自动造 WorkspaceAsyncToolRegistry(..., \".agentscope/bus/async-tools\") （与注释说的「跳过追踪」不一致） agent.channel(T) 实例方法 懒建一个内部 HarnessGateway 并把 channel 接上去 这个网关 没有 ChannelManager / MessageBus ：能路由、能串行，不能主动投递、不能事件回放 GatewayBootstrap.builder()…build() 多 agent + 外部渠道的统一装配：注册 agent、建 ChannelManager 、装分布式子 agent registry build() 不启动渠道、不建 bus；要自己 start() ，并自己 new WakeupDispatcher 三个 builder 方法： HarnessAgent.java:1967-1996 ；workspace 默认 bus / registry： HarnessAgent.java:2504-2516 ； channel(T) ： HarnessAgent.java:646-650 ； build() 里的装配： GatewayBootstrap.java:264-329"},{"p":"appendix/api-cheatsheet.html","n":"C API 速查：Builder 方法按能力分组","s":"recipes","t":"五份配方：直接抄的完整 builder","x":"五段都只省了 main 方法和少量 import，其余可以直接粘。原则是 按场景挑一份，别叠加 ： 每多一个中间件，出问题时你就多一层要排查的东西。"},{"p":"appendix/api-cheatsheet.html","n":"C API 速查：Builder 方法按能力分组","s":"snippet-minimal","t":"1. 最小可跑（core，不到 12 行）","x":"import io.agentscope.core.ReActAgent; import io.agentscope.core.agent.RuntimeContext; import io.agentscope.core.message.Msg; import io.agentscope.core.message.UserMessage; ReActAgent agent = ReActAgent.builder() .name(\"assistant\") .sysPrompt(\"你是一个简洁的中文助手。\") .model(\"dashscope:qwen-plus\") .build(); RuntimeContext ctx = RuntimeContext.builder().userId(\"alice\").sessionId(\"s-1\").build(); Msg reply = agent.call(new UserMessage(\"用一句话解释什么是 Agent\"), ctx).block(); System.out.println(reply.getTextContent());","k":"h3"},{"p":"appendix/api-cheatsheet.html","n":"C API 速查：Builder 方法按能力分组","s":"snippet-production","t":"2. 生产级 core：持久化 + 超时 + 权限","x":"import io.agentscope.core.ReActAgent; import io.agentscope.core.model.ExecutionConfig; import io.agentscope.core.permission.PermissionContextState; import io.agentscope.core.permission.PermissionMode; import io.agentscope.core.state.AgentStateStore; import io.agentscope.core.state.JsonFileAgentStateStore; import java.nio.file.Path; import java.time.Duration; AgentStateStore store = new JsonFileAgentStateStore( Path.of(System.getProperty(\"user.home\"), \".agentscope\", \"state\", \"ops\")); ReActAgent agent = ReActAgent.builder() .name(\"ops-assistant\") .model(\"dashscope:qwen-plus\") .fallbackModel(\"openai:gpt-5.5\") .maxRetries(2) // 含首次：2 = 1 次首发 + 1 次重试 .modelExecutionConfig(ExecutionConfig.builder() .timeout(Duration.ofSeconds(60)) .build()) .toolExecutionConfig(ExecutionConfig.builder() .timeout(Duration.ofSeconds(30)) .build()) .permissionContext(PermissionContextState.builder() .mode(PermissionMode.DEFAULT) .build()) .stateStore(store) .build(); 两个重试旋钮别写混 maxRetries(2) 与 ExecutionConfig.maxAttempts(2) 是同一个计数口径： 都 含首次 。2 表示「1 次首发 + 1 次重试」，不是「首发 1 次再重试 2 次」。","k":"h3"},{"p":"appendix/api-cheatsheet.html","n":"C API 速查：Builder 方法按能力分组","s":"snippet-harness","t":"3. Harness 全功能骨架：工作区 + 压缩 + 子 agent","x":"import io.agentscope.harness.agent.HarnessAgent; import io.agentscope.harness.agent.memory.compaction.CompactionConfig; import java.nio.file.Paths; HarnessAgent agent = HarnessAgent.builder() .name(\"coding-agent\") .agentId(\"coding-agent\") // 状态目录与文件系统命名空间 .model(\"dashscope:qwen-plus\") .workspace(Paths.get(\".agentscope/workspace\")) .compaction(CompactionConfig.builder() .triggerMessages(30) .keepMessages(10) .build()) .enableTaskList() // 长任务让它自己拆 TODO .enablePlanMode() // 先出方案，再动手 .disableWebTools() // 内网/离线部署 .subagentFactory(\"reviewer\", agentName -> HarnessAgent.builder() .name(agentName) .model(\"dashscope:qwen-plus\") .sysPrompt(\"你是代码审查员，只报告真正的问题。\") .build()) .build(); subagentFactory 的 lambda 参数是 子 agent 自己的名字 ，不是任务文本： 框架在物化子 agent 时用这个名字调用工厂，任务则是之后通过 call 传进去的。返回值必须是 Agent ； HarnessAgent 本身实现了 Agent ，所以可以直接返回。","k":"h3"},{"p":"appendix/api-cheatsheet.html","n":"C API 速查：Builder 方法按能力分组","s":"snippet-explore","t":"4. 只读分析：EXPLORE 不是「先问一下」","x":"import io.agentscope.core.ReActAgent; import io.agentscope.core.permission.PermissionContextState; import io.agentscope.core.permission.PermissionMode; ReActAgent agent = ReActAgent.builder() .name(\"explorer\") .model(\"dashscope:qwen-plus\") // EXPLORE：只读工具放行，其余一律 DENY —— 不是挂起等人，是根本不执行 .permissionContext(PermissionContextState.builder() .mode(PermissionMode.EXPLORE) .build()) .build(); 判断依据是工具的 isReadOnly() 。注意内置的 view_text_file / list_directory 等并没有标 readOnly = true ， EXPLORE 下会被拒；自己写的工具要加 @Tool(readOnly = true) 。所以「我只想让 agent 看代码」不能只靠 EXPLORE ，还要补注解。","k":"h3"},{"p":"appendix/api-cheatsheet.html","n":"C API 速查：Builder 方法按能力分组","s":"snippet-unattended","t":"5. 无人值守：不挂起、全拒就停","x":"import io.agentscope.core.ReActAgent; import io.agentscope.core.permission.PermissionContextState; import io.agentscope.core.permission.PermissionMode; import io.agentscope.core.state.JsonFileAgentStateStore; import java.nio.file.Path; ReActAgent agent = ReActAgent.builder() .name(\"nightly-job\") .model(\"dashscope:qwen-plus\") // DONT_ASK：本该 ASK 的降级成 DENY，永远不会挂起等人 .permissionContext(PermissionContextState.builder() .mode(PermissionMode.DONT_ASK) .build()) .stopOnReject(true) // 全被拒就结束，不再烧 token .stateStore(new JsonFileAgentStateStore( Path.of(System.getProperty(\"user.home\"), \".agentscope\", \"state\", \"nightly\"))) .build(); 跑完记得 agent.close() ：它实现了 AutoCloseable ，会把在跑的请求收尾再退出。","k":"h3"},{"p":"appendix/api-cheatsheet.html","n":"C API 速查：Builder 方法按能力分组","s":"noapi","t":"五种「以为有、其实没有」的写法","x":"这些写法在旧版本、别的框架或官方 Python 示例里都出现过，在 2.0.4 的 Java 里会对不上。编译器报 「找不到符号」时先来这里扫一眼。 不存在的写法 为什么 改成 .modelOptions(...) 生成参数不在模型 id 上，也没有这个方法 .generateOptions(GenerateOptions.builder()...build()) toolUseBlock.withInput(...) 内容块是不可变的，没有 withXxx ToolUseBlock.builder().id(原 id).name(原名).input(新参数).build() ， id 必须保留 new RedisAgentStateStore(pool) 没有这个构造器 RedisAgentStateStore.builder().jedisClient(unifiedJedis).build() ，也支持 Lettuce / Redisson 适配 agent.getAgentName() Agent 接口没有这个名字 ReActAgent#getName() ；别和 EventSource#getAgentName() 混 ExecutionConfig.builder().maxRetries(3) 方法叫 maxAttempts ，且含首次尝试 .maxAttempts(3) = 1 次首发 + 2 次重试"},{"p":"appendix/api-cheatsheet.html","n":"C API 速查：Builder 方法按能力分组","s":"next","t":"接着看什么","x":"名字记得住、但想不起在哪一章讲过：查 附录 A 术语表 编译过了、跑起来却抛异常：查 附录 B 报错速查 ，31 条错误文本与源码逐字一致 想知道某个类到底在哪个包、哪一层：查 附录 D 源码地图 想把这页的 builder 串成一个能跑的工程：回到 第 11 章综合案例"},{"p":"appendix/source-map.html","n":"D 源码地图：agentscope-core 的 20 个包各管什么","s":"how","t":"怎么用这一页","x":"别从头读。 先看下面的「症状 → 包」，带着问题跳进去，读完一个类就回来 每一行给出「管什么」和「先看哪个类」。 类名是入口，不是全部 ：真正的细节往往在它的内部类里 包里文件多不代表重要，只代表可变体多。比如 tool 有 57 个文件，是因为它同时包含注解、注册表、执行器、MCP、内置工具五摊事 在 IDEA 里 Ctrl+N 直接搜类名，比顺着目录点快得多；本页的作用是告诉你 搜什么 一个反直觉的结论：最大的包不是 agent tool 57 个文件、 model 40 个，而 agent 只有 27 个。 这说明框架的核心不是「agent 这个类」，而是它调用的那些零件：模型适配、工具协议、消息与状态。 ReActAgent 本身只负责把零件串成循环——所以遇到问题时， 先怀疑零件，再怀疑循环 。"},{"p":"appendix/source-map.html","n":"D 源码地图：agentscope-core 的 20 个包各管什么","s":"layers","t":"先建立一张分层图","x":"两个模块的关系不是「大模块包含小模块」，而是 同一个引擎 + 不同外壳 ： HarnessAgent 内部持有一个 ReActAgent ，把自己装配的中间件挂到它的循环上。 agentscope-harness · io.agentscope.harness.agent 外壳：工作区、文件系统、沙箱、子 agent、技能、计划模式、消息总线。 它不重新实现循环 ，只往 ReActAgent 上装中间件。 agentscope-core 根 · agent · middleware · hook 循环与编排： ReActAgent 的主循环、 AgentBase 的生命周期与 Hook 分发、 MiddlewareBase 的四类包裹点。 message · event · formatter · model · tool · memory · state · permission · rag · skill 零件：这一层才是日常改代码最常碰的。第 04 ~ 09 章讲的就是它们。 core 的唯一入口类： ReActAgent.java:218 ；harness 的入口： HarnessAgent.java:169"},{"p":"appendix/source-map.html","n":"D 源码地图：agentscope-core 的 20 个包各管什么","s":"core","t":"core：20 个包，按「你为什么会打开它」分四组","x":"包的顺序按「入口 → 契约 → 零件 → 横切」排。第一次读源码时，建议只读前两组；第三组等遇到具体问题时再按行跳。"},{"p":"appendix/source-map.html","n":"D 源码地图：agentscope-core 的 20 个包各管什么","s":"packages-entry","t":"1. 入口与循环（5 个包）","x":"包 文件 管什么 先看哪个类 core （根） 2 模块的公开入口与版本号 ReActAgent ；还有一个 Version agent 27 Agent 契约、基类生命周期、运行时上下文、运行控制 Agent / AgentBase / RuntimeContext middleware 8 中间件契约：四类 Input + 链式执行 + 两个内置实现 MiddlewareBase （一个类包住四个切点） hook 20 旧版切点回调： HookEventType 有 12 个枚举常量，另有 15 个 HookEvent 类与分发器；20 是含 recorder/ 子包的文件数 Hook / HookEventType ；新代码优先用 middleware interruption 3 中断的「谁在中断、中断到哪一步」 InterruptControl shutdown 10 优雅停机：JVM 钩子、在跑请求收尾、状态落盘 GracefulShutdownManager","k":"h3"},{"p":"appendix/source-map.html","n":"D 源码地图：agentscope-core 的 20 个包各管什么","s":"packages-contract","t":"2. 内容与契约（4 个包）","x":"包 文件 管什么 先看哪个类 message 23 消息与内容块：4 种 role、12 种内容块相关类型、两个状态枚举 Msg ；配 GenerateReason / ToolCallState event 35 对外事件流：31 种事件 + ConfirmResult + 发射器 AgentEvent / AgentEventType formatter 6 把消息翻译成各家模型要的 JSON，再把回包翻译回来 AbstractBaseFormatter ； 厂商差异都在这里 exception 1 把多个异常聚合成一个 CompositeAgentException","k":"h3"},{"p":"appendix/source-map.html","n":"D 源码地图：agentscope-core 的 20 个包各管什么","s":"packages-runtime","t":"3. 执行与治理（8 个包）","x":"包 文件 管什么 先看哪个类 model 40 模型抽象、注册表、生成参数、执行配置、工具 schema；含 transport 22 个 Model / ModelRegistry tool 57 注解、 ToolBase 、注册表、执行器、分组、MCP、内置工具 Toolkit / ToolBase / ToolExecutor memory 8 进上下文的那串消息，以及长期记忆的两种接法 Memory / StateBackedMemory / LongTermMemory state 17 会话状态存哪、怎么存、冲突怎么办；还带任务与计划模式的状态 AgentStateStore / JsonFileAgentStateStore permission 8 五种模式、四种行为、规则表与六步判定引擎 PermissionEngine / PermissionContextState rag 7 知识库抽象、检索模式、检索工具与自动检索 Hook Knowledge / GenericRAGHook skill 17 技能模型、过滤器、仓库、按需加载与工具工厂 AgentSkill / SkillFilter credential 6 模型凭据与 ModelCard ：key 从哪读、怎么匹配 ModelCard ；查「key 为什么没读到」时来","k":"h3"},{"p":"appendix/source-map.html","n":"D 源码地图：agentscope-core 的 20 个包各管什么","s":"packages-crosscut","t":"4. 横切与占位（3 个包）","x":"包 文件 管什么 先看哪个类 tracing 4 链路追踪抽象与 OpenTelemetry 中间件 Tracer / OtelTracingMiddleware util 8 JSON 编解码、消息工具、类型与异常工具 JsonCodec / MessageUtils workspace 1 只有 package-info ：core 不实现工作区 想看工作区去 harness.agent.workspace 为什么 workspace 是个空包 它只留了一份 package-info.java 说明「工作区是 Harness 的概念」。这不是没写完，而是模块边界： core 只承诺「状态可存可取」，不承诺「工作区目录长什么样」。所以你在 core 里永远找不到 WorkspaceManager 。","k":"h3"},{"p":"appendix/source-map.html","n":"D 源码地图：agentscope-core 的 20 个包各管什么","s":"core-sub","t":"core 里值得单独记住的 15 个子包","x":"子包只在「主包太杂」时才拆。下面这些名字会反复出现在堆栈里，先混个脸熟： 子包 文件 一句话 model.transport 22 HTTP / SSE 传输与请求体拼装；抓包对不上时先来这里 model.spi 1 ModelProvider ：所有厂商扩展实现的唯一接口 tool.mcp 7 MCP 客户端封装、内容转换、 McpTool tool.file 3 ReadFileTool / WriteFileTool / 路径工具 tool.coding 4 ShellCommandTool + Unix / Windows 命令校验器 tool.subagent 3 把子 agent 包成工具的 SubAgentTool tool.builtin 1 TodoTools ：任务清单工具 agent.accumulator 5 流式增量拼装：文本、思考、工具调用各一个累加器 agent.config 4 ModelConfig / ReactConfig / FailoverListener agent.user 4 UserAgent 与流式用户输入（人工输入型 agent） hook.recorder 1 JsonlTraceExporter ：把切点落成 JSONL rag.model 3 Document / DocumentMetadata / RetrieveConfig skill.repository 5 Classpath / FileSystem / RuntimeContext 三种仓库实现 skill.util 3 MarkdownSkillParser 等解析工具 state.legacy 1 ToolkitState ：旧状态迁移用"},{"p":"appendix/source-map.html","n":"D 源码地图：agentscope-core 的 20 个包各管什么","s":"harness","t":"harness：根包 4 个类 + 15 个子包","x":"io.agentscope.harness.agent 根下只有四个文件： HarnessAgent 、 HarnessAgentBuilderSupport （装配逻辑）、 DistributedStore （分布式组件聚合）、 IsolationScope （隔离范围）。剩下的全在子包里， 按能力分，不按层分 。 子包 文件 管什么 内含 middleware 20 Harness 的全部「加装行为」：压缩、记忆、计划模式、子 agent、团队、收件箱 18 个中间件类 + 1 个接口 + 1 个 record；20 是文件数 tool 18 内置工具：文件、Shell、联网、记忆、计划、子 agent、团队、异步等待 — tools 9 工具配置与 MCP 注册： ToolsConfig 、 McpServerRegistrar 、 ToolFilter 注意：单数 tool 是工具，复数 tools 是配置 workspace 7 工作区管理、路径策略、索引、路径归一化 plan 1（计划模式） filesystem 33 文件系统抽象与组合：复合、覆盖、路由、本地、远程、沙箱 model 12、 remote 5、 sandbox 4、 spec 3、 local 2、 util 1 sandbox 45 沙箱生命周期、状态、快照、工作区投影 snapshot 9、 layout 8、 impl 5、 json 1 skill 33 工作区技能仓库与运行时 curator 23、 runtime 7 subagent 27 子 agent 声明、工厂、后台任务、远程协议 task 13、 protocol 6 memory 12 长期记忆配置、flush、合并、后台任务 compaction 4、 session 4 gateway 34 对外网关：会话轮次租约、子 agent 桥接、渠道路由 channel 17 team 11 AgentTeams：客户端、上下文、消息、任务 — transcript 4 会话转录：分段追加存储 文件系统 / 对象存储两种实现 bus 6 消息总线与异步工具注册表 工作区版实现各一个 artifact 3 deliver_artifact 的请求、结果、目标 — coordination 3 周期门闩：本地版、存储版、接口 记忆维护的「多久跑一次」"},{"p":"appendix/source-map.html","n":"D 源码地图：agentscope-core 的 20 个包各管什么","s":"harness-sub","t":"harness 的 18 个二级子包","x":"只有前一行表格里「内含」不为空才展开。名字很长的，基本可以望文生义；这里只补一句最容易猜错的。 二级子包 文件 一句话 filesystem.util 1 FilesystemUtils ：路径与流的共用工具 filesystem.model 12 文件系统的数据模型： FileInfo 、 ReadResult 、 GrepResult 等 filesystem.remote 5 RemoteFilesystem ：走网络的文件系统 filesystem.sandbox 4 沙箱文件系统的四种包装（含「钉住」版本） filesystem.spec 3 LocalFilesystemSpec / SandboxFilesystemSpec / RemoteFilesystemSpec filesystem.local 2 LocalFilesystem 与带 Shell 的版本 sandbox.snapshot 9 沙箱快照：本地 / 远程 / 空实现各一套 sandbox.layout 8 工作区投影的条目类型：文件 / 目录 / 挂载 / Git 仓库 sandbox.impl 5 目前只有 Docker 一种实现 sandbox.json 1 HarnessSandboxJacksonModule ：沙箱状态的序列化模块 skill.curator 23 技能治理：候选、晋升门禁、可见性过滤、审计、安全扫描 skill.runtime 7 技能运行时：目录、加载工具、提示词构建、市场暂存 subagent.task 13 后台子 agent 的任务模型与仓库 subagent.protocol 6 远程子 agent 的事件协议与编解码 gateway.channel 17 渠道抽象 （Channel / Binding / Router）；具体飞书钉钉适配在 extensions 里 memory.compaction 4 压缩配置、会话压缩器、token 计数、工具结果驱逐配置 memory.session 4 会话树、新鲜度评估、转录写入 workspace.plan 1 PlanModeManager ：计划模式的落盘与恢复"},{"p":"appendix/source-map.html","n":"D 源码地图：agentscope-core 的 20 个包各管什么","s":"paths","t":"六条「症状 → 包」的追踪路线","x":"这六条覆盖了前 18 章会遇到的绝大多数问题。每条都按 从外到内 的顺序排，先看最外层。 模型返回的东西不对 model.transport （HTTP / SSE 原样）→ formatter.AbstractBaseFormatter （转成 ContentBlock ）→ message.Msg 。断点打在 formatter 上，能立刻分清是「厂商没给」还是 「框架没解析」。 工具没被调用，或参数是空的 tool.Toolkit （注册）→ tool.ToolSchemaGenerator （给模型看的 schema）→ tool.ToolExecutor （真正执行）→ ToolResultBlock 。MCP 工具先看 tool.mcp.McpTool ，它的调用链多一层客户端。 agent 为什么停了 先读 Msg.getGenerateReason() 的 12 个值，再进 ReActAgent 主循环找对应分支， 最后才看 event.AgentEndEvent 。 别先怀疑模型 ：一半的「它不继续了」是 MAX_ITERATIONS 或 PERMISSION_ASKING 。 重启后状态没了 state.AgentStateStore （存在哪、key 是什么）→ memory.StateBackedMemory （怎么读回）→ ReActAgent 的加载与保存。Harness 还要多查一层 workspace.WorkspaceManager ：状态和工作区是两个地方。 Harness 多出来的行为从哪来 harness.agent.middleware 的 20 个类，名字就是功能。最快的办法是在 HarnessAgent.build() 里搜 inner.middleware ，能看到它们的 安装顺序 —— 顺序决定谁先看到消息。 渠道消息没回复，或后台结果永远不回来 gateway.channel.ChannelRouter （选了哪个 agent、哪个会话键）→ gateway.HarnessGateway （sessionId、轮次锁）→ bus.MessageBus （inbox / 唤醒队列）→ gateway.WakeupDispatcher （谁被叫醒）→ middleware.InboxMiddleware （结果什么时候被注入）。断点先打在 resolveRoute ：五成问题是 routing binding 写错后静默落到了主 agent。 中间件安装位置（搜 inner.middleware ）： HarnessAgent.java:2520 ；消息与原因枚举： GenerateReason.java:36"},{"p":"appendix/source-map.html","n":"D 源码地图：agentscope-core 的 20 个包各管什么","s":"extensions","t":"扩展到哪去找：不在 core / harness 里的那些","x":"本站覆盖 core 与 harness（第 01–18 章），但你看源码时一定会跳到别的模块。记住包名规律就够了： 模块 包名 典型实现 模型厂商 io.agentscope.extensions.model.<provider> DashScopeModelProvider 实现 model.spi.ModelProvider 状态存储 io.agentscope.extensions.<store> RedisAgentStateStore （在 .redis.state ）；MySQL / Postgres / Mongo 提供的是 *DistributedStore ，对应 Harness 的 distributedStore(...) RAG io.agentscope.extensions.rag.<vendor> Dify / RagFlow / Bailian / Haystack 长期记忆 io.agentscope.extensions.memory.<vendor> Mem0 / ReMe / 百炼记忆 渠道 io.agentscope.extensions.channel.<vendor> 飞书 / 钉钉 / 企微 / GitHub / GitLab 找扩展代码的最快办法：从 SPI 反查 核心只认两个 SPI： model.spi.ModelProvider 和 AgentStateStore 。 在 IDEA 里对接口按 Ctrl+Alt+B （Show Implementations），所有扩展实现会一次列出来， 比按模块名猜路径可靠。"},{"p":"appendix/source-map.html","n":"D 源码地图：agentscope-core 的 20 个包各管什么","s":"read","t":"读源码的三条建议","x":"先读接口，再读唯一实现。 Agent 只有四个承诺， Model 只有几个方法；读完契约再看实现，不会被 27 个辅助类淹掉 把 builder 当功能清单。 ReActAgent 43 个、 HarnessAgent 97 个方法，按能力分组就是一份路线图（见 附录 C ） 测试是最好的用例。 agentscope-core/src/test 与 agentscope-harness/src/test 里有大量「最小可复现」，比读实现快 关于这一页的数字 308 与 269 是 2.0.4 快照 下 src/main/java 里 .java 文件的递归计数， 不含测试与扩展模块；同一个文件只算一次。换版本后数字一定会变，但 包的划分很少变 —— 这页真正有用的是「哪个包管什么」，不是具体数字。"},{"p":"appendix/source-map.html","n":"D 源码地图：agentscope-core 的 20 个包各管什么","s":"next","t":"接着看什么","x":"想按功能查 builder 方法： 附录 C API 速查 报错文本对不上： 附录 B 报错速查 概念名字想不起来： 附录 A 术语表 想把这些包串成一条真实调用链： 第 11 章综合案例"},{"p":"appendix/errata.html","n":"E 勘误汇总：官方文档 vs 2.0.4 源码","s":"how","t":"怎么用这一页","x":"遇到「文档说可以、实际不生效」先来这里查 ：按章找，比翻 19 页正文快 看「影响」那一列决定要不要改代码 ：写了会编译不过的，优先级最高；只是默认值不同的，知道就行 两套出处都能点 ：文档那侧是 docs/v2/zh/** 的 md，源码那侧是 agentscope-java-2.0.4 的 Java 文件 结论只对 2.0.4 负责 ：升级后先重新核对，别把这里的「未接线」当成永远成立 三类偏差，处理方式不同 写错了 ：按文档写会编译不过或配置无效，以源码为准； 写旧了 ：文档比代码旧，先搜类名确认缺口是否已补； 没写全 ：文档只写 happy path，默认值、分支和隐藏字段要自己去源码里找。下面的表格里，三种都会遇到。"},{"p":"appendix/errata.html","n":"E 勘误汇总：官方文档 vs 2.0.4 源码","s":"top","t":"最该先知道的 8 条","x":"如果只看一分钟，看这八行——它们是最容易让人「照着文档做了一天，结果全白干」的偏差。 你会怎么踩 一句话真相 详情 明明 .stopOnReject(true) 了，拒绝后模型还在重试 这个值只被存进 ReactConfig ，core 主循环没有任何读取点 08 章 · stopOnReject 没配 compaction(...) ，长会话却被压缩，还冒出 MEMORY.md 压缩与工具结果逐出 默认就是开的 ，两个 disable 都是 false 15 章 · 默认值 tools.json 写了 allow ， agent_spawn 却还能用 agent_spawn 在平台工具名单里，默认 穿透 allow 17 章 · 平台工具 改了 subagents/*.md 的内容，运行中的 agent 没反应 默认装的是 Dynamic（每轮重载）；静态模式只补新名字，同名修改不生效 14 章 · 两条加载路径 以为沙箱是「每个会话一个容器」，结果同用户多个会话共用一个 isolationScope 源码默认落 USER ，文档有两处写成 SESSION 13 章 · isolationScope plan_exit 按文档传 rationale ，不报错但计划没退出 input schema 里只有一个 summary ，多余字段被静默忽略 17 章 · plan_exit 参数 照抄 LocalApprovalGate.defaultPrompter() ，技能晋升永远批不下来 它永远返回 Defer ，javadoc 自己写着 “never approves” 16 章 · 默认闸门 市场技能按文档的三段路径找脚本，死活找不到 实际是四段： .skills-cache/<scope>/<source>/<name>/ 16 章 · 市场缓存路径"},{"p":"appendix/errata.html","n":"E 勘误汇总：官方文档 vs 2.0.4 源码","s":"by-chapter","t":"按章查","x":"只列有偏差的 19 章（04、08–10、12–18、21、29–33、35–36）。01–03、05–07、11、19–20、22–28、34 与附录 A–D、F 没有发现「文档与源码不一致」的条目，不代表它们没有坑， 而是那些坑在正文的「陷阱与窍门」里，不属于勘误。同一处文档被两章引用时（Docker 镜像、isolationScope、本地状态存储强度）， 两章都会列一次，方便按章阅读。"},{"p":"appendix/errata.html","n":"E 勘误汇总：官方文档 vs 2.0.4 源码","s":"ch04","t":"04 · 消息与事件（1 条）","x":"官方说法 2.0.4 源码事实 影响 官方事件类型表没有 AGENT_RESULT ，只写到 AGENT_END AgentEventType 里确实有 AGENT_RESULT ，它携带最终 Msg AgentEventType.java:45 想从事件流里重建最终消息，只等 AGENT_END 会拿到空结果； call() 能返回值靠的正是它","k":"h3"},{"p":"appendix/errata.html","n":"E 勘误汇总：官方文档 vs 2.0.4 源码","s":"ch08","t":"08 · 权限与人机交互（5 条）","x":"官方说法 2.0.4 源码事实 影响 「建议规则」一键免问： ConfirmResult.acceptedRules 、 toolCall.getSuggestedRules() 这两个 API 不存在 ； suggestedRules 只生成，全仓没有 getSuggestedRules() 的消费点 PermissionDecision.java:93 照抄文档会编译不过；要「不再问」，得自己把默认建议写成 PermissionRule 塞进 ConfirmResult.rules ACCEPT_EDITS 自动放行工作目录内的编辑（ workingDirectories 驱动） PermissionEngine 全文不读 getWorkingDirectories() ； ACCEPT_EDITS 只按 isReadOnly() 放行 PermissionEngine.java:210 以为配了目录白名单就安全，实际目录内写工具仍走规则；要目录级控制得自己写 PermissionRule .stopOnReject(true) ：拒绝即终止循环 值只被赋进 ReactConfig ，core 里除了赋值与 getter 没有读取点 ReActAgent.java:5241 拒绝后模型会继续下一轮；要「一拒就停」，用中间件监听 AllToolsDeniedEvent 再发 RequestStopEvent 内置危险路径保护： ToolDangerousPathConstants + isDangerousPath() 常量表与符号链接解析都在，但生产代码零调用点；内置文件工具是注解工具，不走 ToolBase ToolDangerousPathConstants.java:37 以为框架会拦 .env / .ssh ，实际不会；要保护就自己继承 ToolBase 并在 checkPermissions 里调 只读模式下，读操作应当自动放行 @Tool.readOnly 默认 false ，内置的 view_text_file / list_directory 都没标 Tool.java:107 EXPLORE 下连读文件都会被拒；要么给工具补 readOnly = true ，要么别用 EXPLORE","k":"h3"},{"p":"appendix/errata.html","n":"E 勘误汇总：官方文档 vs 2.0.4 源码","s":"ch09","t":"09 · Middleware 与 Hook（3 条）","x":"官方说法 2.0.4 源码事实 影响 onSystemPrompt 画在 onReasoning 里面，「每次组装 system prompt 时触发」 实际在 AgentBase.notifyPreCall() 里调一次 seedSystemMsg() ， 每次 call 只跑一次 ，不在每轮 reasoning 里 AgentBase.java:744 把「每轮都要刷新的时间/预算」写在这里，只会拿到第一次的值；逐轮逻辑放 onReasoning 文档的 TimingMiddleware 、 DynamicContextMiddleware 示例没有 RuntimeContext ctx 参数 MiddlewareBase 的五个方法签名都带 ctx MiddlewareBase.java:59 照抄直接编译不过；以接口签名为准，IDE 里实现一次就知道参数顺序 任务清单示例既 toolkit.registerTool(new TodoTools()) 又 enableTaskList(true) enableTaskList 自己就会注册 TodoTools 并加 TaskReminderMiddleware ReActAgent.java:5560 同一套能力注册两遍，同名工具被覆盖，不报错但没必要；只留 enableTaskList(true)","k":"h3"},{"p":"appendix/errata.html","n":"E 勘误汇总：官方文档 vs 2.0.4 源码","s":"ch10","t":"10 · ReActAgent 与 HarnessAgent（1 条）","x":"官方说法 2.0.4 源码事实 影响 「已有 ReActAgent ？用 fromAgent(...) 升级成 Harness」 javadoc 明说 搬完并不行为等价 ：Harness 会额外装工作区投影、tracing、默认 skill/subagent 中间件，还会替你补一个落盘的 JsonFileAgentStateStore HarnessAgent.java:1417 迁移后行为、磁盘产物、上下文都会变；不是「换个类名」的升级，迁移前先跑对比用例","k":"h3"},{"p":"appendix/errata.html","n":"E 勘误汇总：官方文档 vs 2.0.4 源码","s":"ch12","t":"12 · 工作区与文件系统（5 条）","x":"官方说法 2.0.4 源码事实 影响 Docker spec 的 isolationScope 默认值是 SESSION filesystem.md:137 字段默认是 null ，由 build() 统一落 USER HarnessAgent.java:2415 按 SESSION 估算容器数会算多：同一个用户开多个会话其实共用一个容器（同一隔离键） Docker 的 image 标成「必填」 filesystem.md:136 DockerSandboxClientOptions 有默认值 ubuntu:22.04 ， create() 里还有兜底 DockerSandboxClientOptions.java:36 不写也能起，但默认镜像没有 python3、常用工具， edit_file 之类会莫名其妙失败 模式 1 的路由表列了 7 行（9 个路径项），没有 plans/ filesystem.md:62 源码路由表里有 plans/ 这一条 RemoteFilesystemSpec.java:268 按文档排查「计划文件写到哪去了」会找不到落点；实际 plans/ 也进 KV read 的 limit 默认值未提 接口 javadoc 说默认 2000 行 AbstractFilesystem.java:61 ，但 FilesystemTool 传 0 表示「全部行」 以为天然有 2000 行保护，实际工具层不做限制；大文件一次读进上下文，很容易把窗口打满 workspace.md 把 remote 与 sandbox 两种模式一起说成「本地 store 会报错」 remote 抛异常 :2431 ，sandbox 只 log.warn :2459 sandbox 下漏配分布式 store 不会启动失败，多副本时会静默各写各的","k":"h3"},{"p":"appendix/errata.html","n":"E 勘误汇总：官方文档 vs 2.0.4 源码","s":"ch13","t":"13 · 沙箱与受控执行（5 条）","x":"官方说法 2.0.4 源码事实 影响 Docker 的 image 标「必填」 filesystem.md:136 默认 ubuntu:22.04 ， create() 里还有兜底 DockerSandboxClientOptions.java:36 示例看起来「必须写」；不写能跑，但默认镜像缺 python3， edit_file 会返回 unexpected server response filesystem.md 两处写「后端默认 SESSION」 filesystem.md:137 :237 spec 字段是 null SandboxFilesystemSpec.java:44 ， build() 落 USER HarnessAgent.java:2415 ； sandbox.md 自己的表也写 USER 是默认 sandbox.md:44 ——两篇文档互相矛盾 按 SESSION 规划容量会偏大；实际同用户多会话复用容器，跨用户才隔离 把 OssSnapshotSpec / RedisSnapshotSpec / JdbcSnapshotSpec 列成 harness 的东西 sandbox.md:74-76 harness 只有 Noop / Local / Remote 三种 SandboxSnapshot.java:32-36 ；那三个在 oss / redis / mysql / jdbc 扩展模块里，且都 extends RemoteSnapshotSpec 只引 agentscope-harness 找不到那三个类；要快照到 Redis/OSS 得额外引扩展模块 execute 的默认超时未提 工具层写死 30 秒 ShellExecuteTool.java:78 ，沙箱层的 120 秒只在传 null 时生效 AbstractBaseSandbox.java:214-216 想改超时得让模型显式传 timeout ；改沙箱层默认值没用，永远收不到 null 「多副本部署必须配分布式 store」 sandbox.md:111 确实只是 log.warn ，与 remote 模式的硬抛异常不同 HarnessAgent.java:2431-2439 :2459 「必须」听起来会拦住你，实际只 warn；多副本上线前把这条 warn 当失败处理","k":"h3"},{"p":"appendix/errata.html","n":"E 勘误汇总：官方文档 vs 2.0.4 源码","s":"ch14","t":"14 · 子 Agent 与团队（4 条）","x":"官方说法 2.0.4 源码事实 影响 工作区 spec 的 front matter 示例里写了 name: researcher （ subagent.md:293-301 ） Loader 从不读 name ，名字由文件名派生；未知键被 YAML 读入后直接忽略，不报错也不警告 AgentSpecLoader.java:217-347 以为改 name 就能改名，实际 agent_spawn 里用的是文件名；写不写都不影响结果 「后台任务完成 → 下一轮前以 <system-reminder> 注入」（ subagent.md:145-157 ） 这段代码在静态 SubagentsMiddleware 里；默认装的是 Dynamic，它只渲染任务摘要，不 drain delivery。默认路径的推送来自 completion callback → inbox → InboxMiddleware ，文案是 <system-notification> DynamicSubagentsMiddleware.java:147-172 、 HarnessAgent.java:2327-2346 照文档去找 system-reminder 会以为推送没生效；实际要看 HintBlockEvent 里的 system-notification agent_generate 「默认关闭」，示例只给一句「拿到 builder 内部的 SubagentsMiddleware 引用」 全仓没有生产调用点： enableAgentGenerateTool 只出现在定义与 javadoc 里， build() 不调它，builder 也没有对应方法； HarnessAgent 只暴露 getSubagentAgentManager() 与 getTaskRepository() SubagentsMiddleware.java:251-270 、 HarnessAgent.java:518-545 想「运行时让 agent 自己生成子 agent」在这版做不到；只能预先写 spec 或编程式声明 「 mode: subagent 表示只能作为子 agent」 只有 PRIMARY 被强制（ createAgentIfPresent 直接返回 empty）； SUBAGENT 没有被顶层入口拦截——javadoc 自己写了「current core does not own that check」 SubagentDeclaration.java:68-82 、 DefaultAgentManager.java:107-120 标了 subagent 的声明仍可能被当作主 agent 使用；想强约束得在入口自己校验","k":"h3"},{"p":"appendix/errata.html","n":"E 勘误汇总：官方文档 vs 2.0.4 源码","s":"ch15","t":"15 · 压缩、记忆与逐出（10 条）","x":"官方说法 2.0.4 源码事实 影响 compaction.md ：「压缩与逐出默认关闭，要显式配 compaction(...) 」 Builder 字段默认就是 CompactionConfig.builder().build() 与 ToolResultEvictionConfig.defaults() ，两个 disable 均 false；javadoc 也写 enabled by default HarnessAgent.java:1227-1231 没配也会压缩、也会逐出、也会生成 MEMORY.md ；要「什么都不发生」必须显式关四项 compaction.md ：「工具执行后触发卸载」 在 onReasoning 里做，即 下一次推理前 ，不是工具执行后 ToolResultEvictionMiddleware.java:79-84 想「刚卸完立刻补读」的时序推断会错位；大结果在两次推理之间才被替换 compaction.md ：默认排除工具含 list_files 默认集合只有 6 个： read_file 、 write_file 、 edit_file 、 memory_search 、 memory_get 、 session_search ToolResultEvictionConfig.java:66-73 list_files 的结果 会被逐出 ；文件清单类工具多的时候要自己加进排除集 compaction.md ：压缩前的 flush 由 MemoryFlushMiddleware 触发 由 ConversationCompactor 直接 new 一个 MemoryFlushManager ，不经过 MemoryFlushMiddleware CompactionMiddleware.java:106-109 只给 MemoryFlushMiddleware 配拦截器/开关，管不到压缩前那次 flush compaction.md / memory.md ：offload 到 .log.jsonl 摘要里嵌入的是 resolveContextPath() 返回的 .jsonl ；而每次转写 两份都写 SessionTranscriptWriter.java:166-182 、 SessionTree.java:326-347 按 .log.jsonl 去解析摘要里的引用会找不到；摘要指向另一个（精简）文件 memory.md ：三处 flush 用同一份 flushPrompt 压缩前那次用 2 参构造，固定 DEFAULT_FLUSH_PROMPT MemoryFlushManager.java:95-97 改了 flushPrompt ，压缩前那次还是老风格；同一份 MEMORY.md 出现两种口径 memory.md ：flush 与 offload 都是 fire-and-forget 只有 flush 是；offload 在压缩链路里同步执行，transcript 用 concatWith 阻塞到写完 ConversationCompactor.java:155-183 、 TranscriptMiddleware.java:61-79 每次 call() 会多出几毫秒到几十毫秒（磁盘慢更明显）；对延迟敏感要关 transcript memory.md ：启用记忆后自动获得两个工具， memory_search 最多 30 条 注册 4 个对象、暴露 6 个工具名； memory_search 无条数上限 HarnessAgent.java:2687-2693 、 MemorySearchTool.java:45-89 以为结果天然有上限；搜索范围大时要自己在提示词或工具参数里限条数 memory.md ：溢出恢复的前提是你配了 compaction(...) 默认已配，所以默认就具备恢复能力；反过来说 compaction(null) 会同时失去这条兜底 HarnessAgent.java:958-968 关压缩的同时也关掉了溢出兜底；长会话会直接抛 Context overflow memory.md ：按「天数」归档日流水账 按 文件名里的日期 解析，解析失败直接跳过（ MEMORY.md 因此不受影响） MemoryMaintenanceMiddleware.java:217-241 自己改名或手写的日账不会被归档；想让维护流程接管，文件名必须是 YYYY-MM-DD.md","k":"h3"},{"p":"appendix/errata.html","n":"E 勘误汇总：官方文档 vs 2.0.4 源码","s":"ch16","t":"16 · 技能：从 SKILL.md 到治理（10 条）","x":"官方说法 2.0.4 源码事实 影响 闸门内置三种：「直接拒绝（默认）、本地人工确认、推消息后等」 RejectAllGate 返回的是 Defer ，不是 Reject RejectAllGate.java:23-46 「拒绝」意味着草稿作废；实际是挂起等你手动批，草稿会一直堆着 示例 new LocalApprovalGate(LocalApprovalGate.defaultPrompter()) defaultPrompter() 永远返回 Defer ，javadoc 写 “never approves” :82-88 照抄示例 = 永远批不下来；要真批，用 stdinPrompter 或自己实现返回 Approve 的 gate 「可选叠加一个 LLM 伞合并扫描（默认只 dry-run，输出报告）」 无 LLM 调用；只按前缀聚类写 REPORT.md ，javadoc 明写推迟到未来版本 :248-258 别指望它给出合并建议；报告只能当「哪些技能名字像」的线索 市场技能落在 <wsRoot>/.skills-cache/<source>/<name>/ .skills-cache/<scope>/<source>/<name> ；空 scope 收敛为 _shared :139-200 按三段路径找不到脚本，实际多一层；排查「脚本找不到」时按四段找 「每次调 load_skill_through_path / read_skill 时自动记一笔」 read_skill 在 2.0.4 没有实现，只出现在计数白名单里 :46-54 写提示词时别让模型调 read_skill ；它不存在，只会浪费一轮 load_skill_through_path(skillId, path=\"SKILL.md\") 返回 markdown 正文 返回头部信息 + 完整文档（front matter + 正文），四反引号围栏 :232-256 用返回内容做 patch 时， old_string 要跟含 front matter 的视图对齐 「工作区里的 skill 不用任何注册，把目录放好就生效」 第 3 层的注册前置是 Files.isDirectory(wsInfo.getSkillsDir()) ；第 4 层需要 filesystem != null :896-916 沙箱/远程模式下宿主目录不存在时，第 3 层会静默缺席；技能看起来「没生效」但没报错 使用计数「为后面的清理、灰度发布提供数据」 计数只在已有 created_by 记录时生效，而中间件传的是 skillId 、晋升记的是纯名字 SkillUsageStore.java:184-200 正常链路里 view 计数不会增长；靠计数做灰度会永远看不到流量 「超过 30 天没用的 skill 标为 stale」 只看 created_by=\"agent\" 且未 pinned 的记录；anchor 是 lastUsed/lastViewed/lastPatched 的最大值 :205-241 手写技能、草稿、置顶技能都不会被整理；「清理没用的技能」只能清到 agent 自己造的那批 「用 enableSkillPromotionGate 加审核闸门」 闸门只在 enableSkillManageTool 分支内被消费；没开工具时传了也不生效 :2783-2841 配置看起来生效、实际没装配；只在调 promoteSkill 时才会发现永远 deferred","k":"h3"},{"p":"appendix/errata.html","n":"E 勘误汇总：官方文档 vs 2.0.4 源码","s":"ch17","t":"17 · 计划模式、工具装配与 MCP（9 条）","x":"官方说法 2.0.4 源码事实 影响 plan 阶段白名单是「4 个工具」： plan_enter / plan_write / plan_exit / todo_write plan-mode.md:11 9 个 ：另含 agent_spawn 、 agent_send 、 agent_list 、 task_output 、 task_list PlanModeMiddleware.java:60-70 以为 plan 阶段不能派子 agent，实际可以；只读限制会随 propagatePlanMode 传给子 agent plan_exit 的参数是 rationale （可选） :45 input schema 里只有 summary PlanModeTools.java:162-174 按文档传 rationale 不会报错，只是被 schema 静默忽略；计划退出理由永远是空 拒绝结果是 [Tool denied — plan mode is active]\\nOnly read-only tools and … :70-73 实际是一段以 Blocked: you are in PLAN mode (read-only). 开头的长文案，带「先调查/用 plan_write/准备好再 plan_exit」的指令 :72-76 按文档文案做字符串匹配/断言会失效；日志里搜 Blocked: you are in PLAN mode 「已知缺口：子 agent 不会自动继承只读限制」，建议手动限制或自己开 plan 模式 :151-156 已修 ：构建期 configurePlanMode 下传配置；运行期 propagatePlanMode 对新建与复用的子 agent 强制 enterPlanMode :598-618 、 AgentSpawnTool.java:739-746 再按文档手动限制子 agent，会变成双层限制；排查「子 agent 为什么写不了文件」时先看这条 「不想用文件？直接 builder.toolsConfig(ToolsConfig.builder()...) 」 workspace.md:449 ToolsConfig 里 没有 builder() ：它是一个 100 行的普通 POJO，只能 new + setter ToolsConfig.java:43-99 照文档写直接编译不过；改为 new ToolsConfig() 再逐个 set 「 allow 会连内置工具一起砍，务必把 read_file / memory_search / agent_spawn 一并列出」 :447 agent_spawn 在 37 个平台工具里， 默认活过 allow ； read_file / memory_search 确实会被砍 HarnessPlatformTools.java:35-78 、 ToolFilter.java:77-79 以为白名单能关掉子 agent，实际关不掉；要关得用 deny 或 disableSubagents() 「 tools.json 三种文件系统模式下行为一致，都是 build 时读」 filesystem.md:498-502 沙箱/远端在 build 期可能 读不到 ：catch 后只打 debug、返回空，配置静默失效 ToolsConfigLoader.java:62-74 沙箱模式下 allow/deny 完全没生效，日志里只有 debug；排查工具面时先确认文件被读到了 workspace.md 的 tools.json 仅展示 allow / deny / mcpServers 另有 defaultToolsEnabled 、 strictAllow ；MCP 条目还有 enableTools / disableTools / prefixToolNames / required / timeout / initializationTimeout / queryParams McpServerConfig.java:44-133 不知道这些字段，就只能在「工具为什么全没了」「MCP 为什么超时」之间反复试 「退出 Plan Mode 走 HITL 确认（ ConfirmResult(true) ）」 plan-mode.md:49-66 实际是 PermissionDecision.ask(...) ，走 权限引擎 的确认链，不是另一个 ConfirmResult 回调；因此在 DONT_ASK 下会变成 DENY PlanModeTools.java:180-192 无人值守（ DONT_ASK ）配 plan 模式会卡死；模型反复请求退出、反复被拒，直到耗尽 maxIters","k":"h3"},{"p":"appendix/errata.html","n":"E 勘误汇总：官方文档 vs 2.0.4 源码","s":"ch18","t":"18 · 网关、渠道与异步（7 条）","x":"官方说法 2.0.4 源码事实 影响 「 agent.channel(...) 会在后台自动完成所有接线」 channel.md:17 它只建 HarnessGateway.create() （无 ChannelManager 、无 MessageBus ）。路由与串行可用， 主动投递与网关侧唤醒不可用 HarnessAgent.java:661-667 想主动播报/异步唤醒，必须另建 GatewayBootstrap + WakeupDispatcher ， agent.channel() 不够 「同一 session 的并发消息会公平排队」 channel.md:12 只有默认的 LocalSessionTurnGate 是排队；换成抛 TurnBusyException 的分布式 gate，整轮变成 Mono.empty() ， 静默丢弃 HarnessGateway.java:694-720 用户看到「发出去了没回复」，HTTP 可能是 200 + 空 body；客户端必须把空当「忙，请重试」 全文未出现 MessageBus / InboxMiddleware / AsyncToolMiddleware / WakeupDispatcher 这四样组成「后台结果怎么回到对话」的完整链路，缺一环就表现为「异步没效果」 AsyncToolMiddleware.java:237-294 只配 asyncToolTimeout 不够；没有 bus/dispatcher，占位结果之后永远没有第二轮 「多 HarnessAgent 路由」示例里 .agent(\"sales\", salesAgent) 隐含「 sales 就是路由 id」 只有 非主 agent 用这个 key；主 agent 用 agent.getAgentId() ，为空才退成 \"main\" HarnessGateway.java:159-165 绑主 agent 时写 .agent(\"sales\", mainAgent) 不生效；路由仍落到 main 或它的真实 id DmScope 的四个枚举值描述成四种不同粒度 DmScope.java:18-30 PER_PEER 与 PER_CHANNEL_PEER 生成 完全相同 的 key（channel 本就在第一段） ChannelRouter.java:204-210 以为换了枚举会话会更细，实际没变化；要多一段区分只能用 PER_ACCOUNT_CHANNEL_PEER dispatchStream 被描述成「可选：流式分发」 channel.md:299-304 默认实现是 Flux.error(\"Streaming dispatch not supported\") ， 不会 回退到 dispatch Channel.java:105-107 没实现 dispatchStream 就用流式，会直接报错；要么自己实现，要么走普通 dispatch 没提 GatewayBootstrap 与消息总线、唤醒器的关系 GatewayBootstrap.build() 不建 bus；官方 AsyncSubagentExample 把 bus 只交给 dispatcher，而 agent 因未调 .messageBus(...) 会自动落到 <workspace>/.agentscope/bus ——两边不是同一目录 AsyncSubagentExample.java:66-95 、 HarnessAgent.java:2504-2516 后台任务跑完了却从不触发下一轮；修法是一行：把同一个 bus 实例显式交给 .messageBus(bus) 与 new WakeupDispatcher(bus, gateway)","k":"h3"},{"p":"appendix/errata.html","n":"E 勘误汇总：官方文档 vs 2.0.4 源码","s":"ch21","t":"21 · Managed Agent 定义（1 条）","x":"官方说法 2.0.4 源码事实 影响 控制台范围 1–64，未配置时表单显示 maxIters=12 managed-agent-configuration.md:21 Go 侧落库前对 maxIters <= 0 直接赋 20 managed_definition.go:91-94 表单提交 12，API / 脚本不填或填 0 得到 20；写脚本时显式设置，别依赖默认值","k":"h3"},{"p":"appendix/errata.html","n":"E 勘误汇总：官方文档 vs 2.0.4 源码","s":"ch29","t":"29 · 记忆接入（1 条）","x":"官方说法 2.0.4 源码事实 影响 记忆概览仍把 LongTermMemory 作为跨会话持久化接口，并列出 Mem0、百炼、ReMe 三种实现 overview.md:6-14 LongTermMemory 标了 @Deprecated(forRemoval = true, since = \"2.0.0\") ，注释说明长期记忆已移除，跨会话持久化应在应用层集成 LongTermMemory.java:66-71 ； LongTermMemoryMode 同时弃用 LongTermMemoryMode.java:51-54 三种适配器仍能运行，但新项目应把它当迁移对象；不要据此设计新的记忆架构","k":"h3"},{"p":"appendix/errata.html","n":"E 勘误汇总：官方文档 vs 2.0.4 源码","s":"ch30","t":"30 · 分布式存储（2 条）","x":"官方说法 2.0.4 源码事实 影响 MySQL 分布式页仍用 MysqlDistributedStore.create(dataSource) mysql.md:20-33 该类已标 @Deprecated(since = \"2.1\", forRemoval = true) ，并建议改用 agentscope-extensions-jdbc 的 JdbcDistributedStore MysqlDistributedStore.java:54-60 新项目用 JdbcDistributedStore ；旧类只覆盖 MySQL，且未来会移除 MongoDB 页写会话 TTL 30 天、快照上限 15MB mongodb.md:64 mongodb.md:89 会话 TTL 默认关闭，要显式 ttlDays(n) 才创建 TTL 索引 MongoAgentStateStore.java:84-98 ；快照走 GridFS，255KB 分块，单文件上限 16GB，且无独立 TTL MongoRemoteSnapshotClient.java:40-50 按 30 天 / 15MB 做容量与保留策略会算错；会话不会自动过期，快照可能远超 15MB","k":"h3"},{"p":"appendix/errata.html","n":"E 勘误汇总：官方文档 vs 2.0.4 源码","s":"ch31","t":"31 · Agent 状态存储（1 条）","x":"官方说法 2.0.4 源码事实 影响 分布式 MySQL 页的表结构写 user_id 、 state_value 、 state_type mysql.md:52 旧 MysqlAgentStateStore 实际建的是 session_id 、 state_key 、 item_index 、 state_data （外加 version） MysqlAgentStateStore.java:42-56 :197-203 ；新 JDBC 同样按 (session_id, state_key, item_index) 存 SessionStateDialect.java:21-26 按旧文档列名写 SQL 报表或迁移脚本会失败；以 item_index 模型为准","k":"h3"},{"p":"appendix/errata.html","n":"E 勘误汇总：官方文档 vs 2.0.4 源码","s":"ch32","t":"32 · RAG（3 条）","x":"官方说法 2.0.4 源码事实 影响 RAG 概览示例注释写「或 STATIC 、 NONE 」 overview.md:23 枚举只有 GENERIC 、 AGENTIC 、 NONE RAGMode.java:40-55 照文档写 RAGMode.STATIC 会直接编译失败 Simple 检索参数表列了 metadata simple.md:97-101 RetrieveConfig 只有 limit、scoreThreshold、vectorName、conversationHistory，没有 metadata RetrieveConfig.java:34-37 需要 metadata 过滤时走 provider 配置或向量库层，不要往 RetrieveConfig 上传 RAG 概览仍按 Knowledge 介绍五种实现，并给 .knowledge(...) + .ragMode(...) 接入方式 overview.md:6-25 Knowledge 、 RAGMode 、 RetrieveConfig 都标了 @Deprecated(forRemoval = true, since = \"2.0.0\") ，注释写明 rag 包已移除，检索应在应用层集成 Knowledge.java:30-34 RAGMode.java:28-32 RetrieveConfig.java:28-32 适配器仍能用，但整条内置 RAG 管线是 legacy；新项目把检索做成应用层工具","k":"h3"},{"p":"appendix/errata.html","n":"E 勘误汇总：官方文档 vs 2.0.4 源码","s":"ch33","t":"33 · 协议（1 条）","x":"官方说法 2.0.4 源码事实 影响 A2A 文档写 starter 为 agentscope-spring-boot-starter-a2a-server a2a.md:108-110 仓库实际 artifact 是 agentscope-a2a-spring-boot-starter pom.xml:28 照文档写依赖会解析失败","k":"h3"},{"p":"appendix/errata.html","n":"E 勘误汇总：官方文档 vs 2.0.4 源码","s":"ch35","t":"35 · 技能仓库（1 条）","x":"官方说法 2.0.4 源码事实 影响 快速上手写 new MysqlSkillRepository(ds, true) mysql-repository.md:36-37 ，自定义表名又写五参构造器 mysql-repository.md:83-90 源码只有一个 public 构造器 (DataSource, boolean createIfNotExist, boolean writeable) MysqlSkillRepository.java:174-183 ；库名 / 表名走 builder(ds) :1199-1217 照文档两参 / 五参写法会编译失败","k":"h3"},{"p":"appendix/errata.html","n":"E 勘误汇总：官方文档 vs 2.0.4 源码","s":"ch36","t":"36 · 基础设施与生态（9 条）","x":"官方说法 2.0.4 源码事实 影响 文档写 new NacosA2aRegistryProperties() nacos.md:36-38 ，又写 new NacosAgentCardResolver(props, \"translator-agent\") nacos.md:48-52 NacosA2aRegistryProperties 是四字段 record，没有无参构造器 NacosA2aRegistryProperties.java:34-38 ；解析器只有 (Properties) / (AiService) 两个构造器，Agent 名由 A2aAgent.builder().name(...) 提供 NacosAgentCardResolver.java:75-88 照文档写两处都会编译失败；properties 用 builder() ，resolver 用 (Properties) ，名字交给 A2aAgent Nacos 页写 AgentScopeA2aServer.builder().agentRegistry(...) nacos.md:107-110 builder 必须传 ReActAgent.Builder 或 AgentRunner AgentScopeA2aServer.java:174-184 ，注册方法叫 withAgentRegistry(...) :333 照文档写会编译失败；用 builder(agentBuilder).withAgentRegistry(registry) Higress 快速上手以 .build() 结尾 higress.md:31-34 builder 只提供返回 Mono 的 buildAsync() HigressMcpClientBuilder.java:311 与阻塞式 buildSync() :357 照文档写 .build() 会编译失败；响应式用 async，脚本 / 测试用 sync 文档称 AgentScheduler 核心接口包含 pause(...) / resume(...) scheduler.md:15-20 ，示例还把变量声明成接口后调用 pause scheduler.md:66-73 接口只有 schedule / cancel / get / getAll / shutdown / type，没有 pause / resume AgentScheduler.java:77-190 ；pause / resume 只在 Quartz 实现类上 QuartzAgentScheduler.java:429-470 声明成 AgentScheduler 再调 pause 会编译失败；用具体 Quartz 类型或 ScheduleAgentTask.cancel() 文档让初始化后手动挂 .hook(new StudioMessageHook(...)) studio.md:37-42 StudioManager.initialize() 成功后会自己 AgentBase.addSystemHook(new StudioMessageHook(...)) ，并注册 Tracer StudioManager.java:246-260 自动 Hook 与手动 Hook 同时生效时，同一条最终消息会被推两次 文档说每条 user / assistant / tool 消息都被同步到 Studio studio.md:48-52 StudioMessageHook 只处理 PostCallEvent ，取 getFinalMessage() 推送；失败只记日志 StudioMessageHook.java:66-95 消息 Hook 只覆盖一次调用的最终回复；工具与推理过程看 trace，不要指望这个 Hook 文档说命中采样后「调用替换为 Trinity 后端」 training.md:68-74 生产调用不变；路由器克隆影子 Agent、换成 TrinityModelAdapter ，在异步线程池里再跑一遍 TrainingRouter.java:277-298 ，生产响应不等影子完成 :221-249 Training 是影子流量，不是替换生产模型；采样命中只会多跑一次异步影子 文档说 rewardCalculator 是 Function<AgentBase, Double> training.md:52-58 实际接口是 RewardCalculator ，方法为 double calculate(Agent agent) RewardCalculator.java:26-34 Lambda 仍可写，但参数类型是 Agent ；自定义类实现 RewardCalculator ，不是 Function 文档示例是 adapter.stream(agent, request) chat-completions-web.md:33-37 源码只有一个 stream 重载： stream(ReActAgent, List<Msg>, String requestId, String model) ChatCompletionsStreamingAdapter.java:86-104 照文档写会编译失败；先用 ChatMessageConverter 把请求转成 List<Msg>","k":"h3"},{"p":"appendix/errata.html","n":"E 勘误汇总：官方文档 vs 2.0.4 源码","s":"why","t":"为什么会有这些差异","x":"把 79 条放在一起看，成因其实只有三类，认出类型就能猜出该信哪边： 文档滞后于代码 2.0.x 迭代快，文档按某个早期提交写成，后来行为改了、字段补了，文档没跟上。典型：17 章「子 agent 不继承 plan 模式」的缺口已经修了， 文档还留着「已知缺口」。这类先搜类名/方法名，看源码里有没有新 API。 示例从 1.x 或别的语言搬来 1.x 的 memory.addMessage() 、 StaticLongTermMemoryHook 、Python 部署页的示例，都还在文档站里。典型：09 章示例缺 RuntimeContext 参数（07 章 1.x 记忆 API 整包换成新接口，不在这 79 条里，正文有专段说）。这类先看包级 @Deprecated 与签名。 只写 happy path，不写默认值与兜底 文档说「可以配」，没说「不配时是什么」。典型：15 章压缩默认开启、12 章 Docker 镜像有默认值、18 章 dispatchStream 默认直接报错。 这类必须去 build() 和字段初始化处看默认值。"},{"p":"appendix/errata.html","n":"E 勘误汇总：官方文档 vs 2.0.4 源码","s":"verify","t":"自己核对的三步","x":"这张表会过期。升级版本或怀疑某条结论时，按下面三步复核，比记结论可靠： 搜「读取点」，不只看定义 字段和 setter 存在，不代表有人读。搜字段名在 build() 、中间件、引擎里的出现次数；只有赋值 + getter 的，就是空接线。 08 章的四项、12 章的 useLegacyXmlWorkspaceContext 都是这样确认的。 先找字段默认值，再找 build() 的覆盖 spec 字段写 null ， build() 可能落一个完全不同的默认值（ isolationScope 就是这样从 SESSION 变成 USER 的）。 两处都要看，只看一处就会得出相反结论。 跑一个最小用例，看日志与事件流 默认值、触发时机、返回结构这三类偏差，跑一次比读十遍快：打开 DEBUG 日志、打印事件类型、把返回值原样贴出来。 本页每条「影响」都描述了预期现象，可以直接当验收标准。 别把这张表当成「官方文档不可信」 大部分偏差是「文档没写全」，不是「文档写错」。真正的用法是： 文档负责告诉你有什么，源码负责告诉你现在怎么跑 。 遇到冲突时以 2.0.4 的代码为准，并把版本号记在结论旁边——没有版本号的结论，下个月就可能变成谣言。"},{"p":"appendix/errata.html","n":"E 勘误汇总：官方文档 vs 2.0.4 源码","s":"next","t":"接着看什么","x":"你现在想做什么 去哪 为什么 看某条偏差的完整推导与代码 12 – 18 章 的「官方说了什么 vs 源码实际是什么」 本页只留结论，推导、复现代码和练习在正文 按报错找修法 附录 B：报错速查 31 条错误文本与源码抛出点逐字对齐 按文件找讲解 附录 D：源码地图 core 20 个包 + harness 15 个子包，外加六条追踪路线 按 Builder 方法找写法 附录 C：API 速查 含「五种以为有、其实没有」的写法，与本页互补 直接读官方原文 docs/v2/zh/docs/harness/ 结论以源码为准，但整体设计与取舍仍值得读"},{"p":"appendix/artifacts.html","n":"F 扩展 artifact 速查：能力 → 依赖","s":"goals","t":"读完你能做到","x":"按能力直接找到 artifactId，不再把 provider id 当成依赖坐标 分清「核心扩展」「具体后端」「Spring Boot starter」三层，知道什么时候只引扩展、什么时候还要引 starter 识别已经标记 legacy 的 MySQL 旧类，新项目直接走 JDBC 把站点章节、artifact 与源码 pom.xml 对上，升级时能自己复核"},{"p":"appendix/artifacts.html","n":"F 扩展 artifact 速查：能力 → 依赖","s":"how","t":"怎么用这一页","x":"先找能力，再看 artifact ：例如「要接 Redis」在「状态 / 分布式存储」组，不在「模型」组 再判断要不要 starter ：普通 Java 应用只引扩展；Spring Boot 想要自动装配，再引对应 starter 一个 artifact 可能覆盖多个 id ：OpenAI 兼容模块同时承载 openai 、 deepseek 、 glm 、 kimi 、 minimax 旧类只做兼容 ： MysqlDistributedStore 、 MysqlAgentStateStore 、 MysqlSkillRepository 的旧构造器都不要写进新代码 每一行的 pom.xml 出处都可以点开复核；artifactId 与目录名一致，便于在 IDE 里搜"},{"p":"appendix/artifacts.html","n":"F 扩展 artifact 速查：能力 → 依赖","s":"model","t":"模型：6 个 artifact，10 个 provider id","x":"官方集成表列了 10 个 provider id，但 artifact 只有 6 个；OpenAI 兼容模块承载其中 5 个 index.md:6-17 。 所以「换模型」通常只换 id，不换依赖。 能力 / id artifactId（出处） 说明 章节 openai / deepseek / glm / kimi / minimax agentscope-extensions-model-openai pom.xml:29 通用 Chat Completions 客户端 + 四家兼容 formatter；原生结构化输出默认开 第 28 章 openai-official agentscope-extensions-model-openai-official pom.xml:29 OpenAI 官方 Java SDK，只走 Responses API；没有专用 starter 第 28 章 dashscope / qwen* agentscope-extensions-model-dashscope pom.xml:29 DashScope / 通义千问；支持短名与 thinking 第 28 章 gemini agentscope-extensions-model-gemini pom.xml:29 Gemini API；Vertex AI 需显式 builder 配置 第 28 章 anthropic agentscope-extensions-model-anthropic pom.xml:29 Anthropic Messages API；apiKey 与 authToken 互斥 第 28 章 ollama agentscope-extensions-model-ollama pom.xml:29 本地 Ollama；无必填密钥 第 28 章"},{"p":"appendix/artifacts.html","n":"F 扩展 artifact 速查：能力 → 依赖","s":"memory","t":"记忆：三个后端，一个已弃用接口","x":"Mem0、百炼、ReMe 都实现同一个 LongTermMemory 接口；接口本身从 2.0.0 起已标记弃用， 但三个适配器仍可运行，适合作为迁移对象而不是新项目地基。 能力 artifactId（出处） 说明 章节 Mem0 agentscope-extensions-mem0 pom.xml:31 托管记忆服务；metadata 过滤与固定 topK 5 第 29 章 百炼记忆 agentscope-extensions-memory-bailian pom.xml:31 阿里云托管记忆库；topK 10 / minScore 0.3 第 29 章 ReMe agentscope-extensions-reme pom.xml:31 按 workspace 组织的轨迹记忆；固定 topK 5 第 29 章"},{"p":"appendix/artifacts.html","n":"F 扩展 artifact 速查：能力 → 依赖","s":"store","t":"状态 / 分布式存储：先 JDBC，再按能力补齐","x":"AgentStateStore 与 DistributedStore 共用 Redis / JDBC / MongoDB / OSS 这些后端。 关系型数据库优先 JDBC；旧 MySQL 类只保留兼容，不要写进新代码。 后端 artifactId（出处） 说明 章节 Redis agentscope-extensions-redis pom.xml:31 状态、KV、快照、分布式锁四项齐全；低延迟多副本首选 第 30、31 章 JDBC agentscope-extensions-jdbc pom.xml:31 当前关系型主线，支持 MySQL / PostgreSQL / H2 / SQLite；组件懒加载 第 30、31 章 MongoDB agentscope-extensions-mongodb pom.xml:31 文档型状态 + GridFS 快照；TTL 默认关闭 第 30、31 章 OSS agentscope-extensions-oss pom.xml:31 大快照首选；没有 SandboxExecutionGuard 第 30、31 章 MySQL（legacy） agentscope-extensions-mysql pom.xml:31 MysqlDistributedStore 已标未来移除； MysqlAgentStateStore 是旧实现 第 30、31 章"},{"p":"appendix/artifacts.html","n":"F 扩展 artifact 速查：能力 → 依赖","s":"rag","t":"RAG：五种知识库，整条路径是 legacy","x":"Simple、百炼、Dify、HayStack、RAGFlow 五个适配器仍实现 Knowledge ，但 Knowledge / RAGMode / RetrieveConfig 从 2.0.0 起都已弃用。 新项目更适合把检索做成应用层工具。 实现 artifactId（出处） 说明 章节 Simple agentscope-extensions-rag-simple pom.xml:31 自己管读取、切块、embedding 与向量库；唯一支持写入 第 32 章 百炼 agentscope-extensions-rag-bailian pom.xml:31 托管索引，Java 只检索；写入抛 UnsupportedOperationException 第 32 章 Dify agentscope-extensions-rag-dify pom.xml:31 数据集 + 四种检索模式；topK 10 / 阈值 0.0 第 32 章 HayStack agentscope-extensions-rag-haystack pom.xml:31 复用已有索引流水线；topK 3 / 30 秒超时 / 3 次重试 第 32 章 RAGFlow agentscope-extensions-rag-ragflow pom.xml:31 复杂文档解析；topK 1024 / 阈值 0.2 第 32 章"},{"p":"appendix/artifacts.html","n":"F 扩展 artifact 速查：能力 → 依赖","s":"protocol","t":"协议与兼容层：先看调用方","x":"能力 artifactId（出处） 说明 章节 A2A 客户端 agentscope-extensions-a2a-client pom.xml:30 把远端 A2A Agent 变成本地 Agent；按 AgentCard 解析 第 33 章 A2A 服务端 agentscope-extensions-a2a-server pom.xml:31 组装处理器，不负责监听端口；注册 AgentCard 第 33 章 Agent Protocol agentscope-extensions-agent-protocol pom.xml:29 /tasks 任务 API + SSE / HITL 第 33 章 AG-UI agentscope-extensions-agui pom.xml:28 把 AgentEvent 映射成前端事件流；支持 interrupt / resume 第 33 章 Chat Completions agentscope-extensions-chat-completions-web pom.xml:28 框架无关适配器；HTTP / SSE 路由由 starter 或自写 Controller 提供 第 36 章"},{"p":"appendix/artifacts.html","n":"F 扩展 artifact 速查：能力 → 依赖","s":"channel","t":"渠道：公共组件 + 六个平台适配器","x":"平台 artifactId（出处） 说明 章节 公共 agentscope-extensions-channel-common pom.xml:28 去重、防循环、token 缓存与 Channel 契约 第 34 章 钉钉 agentscope-extensions-channel-dingtalk pom.xml:28 Stream 默认，HTTP 可选；HTTP 可配 aesKey 第 34 章 飞书 agentscope-extensions-channel-feishu pom.xml:28 事件订阅 v2；可选 AES-256-CBC 解密 第 34 章 企微 agentscope-extensions-channel-wecom pom.xml:28 回调全加密；token / timestamp / nonce 验签 第 34 章 微信 agentscope-extensions-channel-weixin pom.xml:40 微信渠道适配器；保留独立模块 第 34 章 GitHub agentscope-extensions-channel-github pom.xml:28 issue / PR 评论 Webhook；HMAC-SHA256 第 34 章 GitLab agentscope-extensions-channel-gitlab pom.xml:28 Note hook；过滤 bot 自身评论 第 34 章"},{"p":"appendix/artifacts.html","n":"F 扩展 artifact 速查：能力 → 依赖","s":"skill","t":"技能仓库：四种来源","x":"来源 artifactId（出处） 说明 章节 Git agentscope-extensions-skill-git-repository pom.xml:31 只读；autoSync 默认开；读前 ls-remote，变化才 pull 第 35 章 MySQL agentscope-extensions-skill-mysql-repository pom.xml:29 在线 CRUD；旧文档构造器不存在，用三参或 builder 第 35 章 PostgreSQL agentscope-extensions-skill-postgresql-repository pom.xml:29 schema 隔离；默认 schema agentscope 第 35 章 Nacos agentscope-extensions-nacos-skill pom.xml:29 只读 ZIP；枚举必须给 knownSkillNames 第 36 章"},{"p":"appendix/artifacts.html","n":"F 扩展 artifact 速查：能力 → 依赖","s":"infra","t":"基础设施：注册、网关、调度","x":"能力 artifactId（出处） 说明 章节 Nacos A2A agentscope-extensions-nacos-a2a pom.xml:29 AgentCard / 端点注册与发现 第 36 章 Nacos Prompt agentscope-extensions-nacos-prompt pom.xml:29 订阅模板、缓存、热更新；缓存键只有 promptKey 第 36 章 Higress agentscope-extensions-higress pom.xml:29 MCP 工具客户端 + 工具搜索 + HigressToolkit 第 36 章 Scheduler 公共 agentscope-extensions-scheduler-common pom.xml:31 AgentScheduler / ScheduleConfig / ScheduleAgentTask 第 36 章 Quartz agentscope-extensions-scheduler-quartz pom.xml:28 本地 / 小集群；CRON、固定速率、固定延迟 第 36 章 XXL-Job agentscope-extensions-scheduler-xxl-job pom.xml:29 只注册 JobHandler；调度在控制台配置 第 36 章"},{"p":"appendix/artifacts.html","n":"F 扩展 artifact 速查：能力 → 依赖","s":"ecosystem","t":"生态：调试与训练","x":"能力 artifactId（出处） 说明 章节 Studio agentscope-extensions-studio pom.xml:28 消息推送、trace、HITL；initialize 自动挂 Hook 第 36 章 Training agentscope-extensions-training pom.xml:28 采样、影子 Agent、reward、周期 commit 第 36 章"},{"p":"appendix/artifacts.html","n":"F 扩展 artifact 速查：能力 → 依赖","s":"service","t":"服务化：把应用接进控制面","x":"能力 artifactId（出处） 说明 章节 External Agent SDK agentscope-extensions-aistio pom.xml:33 Aistio.instrument / newBridge ；注册后进入 Agent 目录 第 22 章"},{"p":"appendix/artifacts.html","n":"F 扩展 artifact 速查：能力 → 依赖","s":"sandbox","t":"沙箱：Docker 之外四个后端","x":"后端 artifactId（出处） 说明 章节 Kubernetes agentscope-extensions-sandbox-kubernetes pom.xml:31 Pod 级隔离；适合已有 K8s 集群 第 13 章 AgentRun agentscope-extensions-sandbox-agentrun pom.xml:31 托管沙箱运行时 第 13 章 Daytona agentscope-extensions-sandbox-daytona pom.xml:31 远程开发环境型沙箱 第 13 章 E2B agentscope-extensions-sandbox-e2b pom.xml:31 托管代码执行沙箱 第 13 章"},{"p":"appendix/artifacts.html","n":"F 扩展 artifact 速查：能力 → 依赖","s":"starters","t":"Spring Boot starter：自动装配层","x":"starter 只负责装配，不替代扩展 artifact。模型 starter 通常只在 agentscope.model.provider 匹配且容器里没有现成 Model bean 时创建模型。 starter artifactId（出处） 装配什么 章节 核心 agentscope-spring-boot-starter pom.xml:28 ReActAgent 基础装配与默认配置 第 28 章 OpenAI agentscope-openai-spring-boot-starter pom.xml:28 agentscope.model.provider=openai 时创建 OpenAI 模型 第 28 章 DashScope agentscope-dashscope-spring-boot-starter pom.xml:28 DashScope 模型自动配置 第 28 章 Anthropic agentscope-anthropic-spring-boot-starter pom.xml:28 Anthropic 模型自动配置 第 28 章 Gemini agentscope-gemini-spring-boot-starter pom.xml:28 Gemini 模型自动配置 第 28 章 Ollama agentscope-ollama-spring-boot-starter pom.xml:26 本地 Ollama 模型自动配置 第 28 章 Nacos agentscope-nacos-spring-boot-starter pom.xml:28 A2A 注册发现、Prompt 配置中心 第 36 章 A2A agentscope-a2a-spring-boot-starter pom.xml:28 A2A 服务端自动配置 第 33 章 AG-UI agentscope-agui-spring-boot-starter pom.xml:28 AG-UI 事件流与路由 第 33 章 Chat Completions agentscope-chat-completions-web-starter pom.xml:32 /v1/chat/completions 控制器与 SSE 第 36 章"},{"p":"appendix/artifacts.html","n":"F 扩展 artifact 速查：能力 → 依赖","s":"coverage","t":"覆盖矩阵：官方文档 → 本站章节 → 源码入口","x":"这一张表用来回答「我该从哪进」和「有没有漏」：左边是官方集成目录，中间是本站章节，右边是源码入口。 官方集成总览覆盖模型、记忆、分布式、会话、RAG、协议、渠道、技能、基础设施与生态 overview.md:8-113 。 官方文档 本站章节 源码入口 边界 / 备注 integration/model/** 28 ModelRegistry / ModelProvider ModelRegistry.java:44 ModelProvider.java:22 10 个 id / 6 个 artifact；id 不等于 artifact integration/memory/** 29 LongTermMemory LongTermMemory.java:66-71 接口从 2.0.0 起弃用，适配器仍可运行 integration/distributed/** 30 DistributedStore DistributedStore.java:30-73 JDBC 是当前关系型主线；旧 MySQL 类兼容 integration/session/** 31 AgentStateStore AgentStateStore.java:22-38 状态不是聊天记录；版本与冲突策略分开选 integration/rag/** 32 Knowledge Knowledge.java:30-34 整条内置 RAG 管线是 legacy integration/protocol/** 33 A2A / Agent Protocol / AG-UI AgentScopeA2aServer.java:83 AgentProtocolController.java:42 三个方向，不是三个 endpoint integration/channel/** 34 Channel Channel.java:20 入站适配器；去重 / 防循环默认在 JVM 内 integration/skill/** 35 AgentSkillRepository AgentSkillRepository.java:35 Git 只读；数据库可写；Nacos 是只读 ZIP integration/infrastructure/** 36 / 36A-1 / 36A-2 / 36A-3 Nacos / Higress / Scheduler NacosA2aRegistry.java:39 HigressToolkit.java:56 治理在网关；调度状态在 Quartz / XXL-Job integration/ecosystem/** 36 / 36A-4 / 36A-5 Studio / Training / Chat Completions StudioManager.java:53 TrainingRunner.java:83 Studio 开发期；Training 影子流量；Chat 是协议适配 service/** 19–26 / 22 Aistio / Helm Aistio.java:57 调用 Endpoint 不需要运行时 SDK docs/** （核心 / Harness） 00–18 ReActAgent / HarnessAgent ReActAgent.java:218 本站的地基；扩展都建立在这些契约上"},{"p":"appendix/artifacts.html","n":"F 扩展 artifact 速查：能力 → 依赖","s":"version","t":"版本与选型提醒","x":"版本统一 ：所有 artifact 跟根 revision 走，当前是 2.0.4 pom.xml:30 ；不要给单个扩展写别的版本。 先扩展，后 starter ：普通 Java 应用不需要 starter；Spring Boot 只有在需要自动装配时才加。 模型看 id，不看 artifact ： deepseek: 等五个 id 共用 OpenAI 兼容 artifact。 关系型存储优先 JDBC ： MysqlDistributedStore / MysqlAgentStateStore 都是兼容层。 RAG / 记忆是 legacy ：适配器可用，但新项目优先应用层集成。"},{"p":"appendix/artifacts.html","n":"F 扩展 artifact 速查：能力 → 依赖","s":"next","t":"接着看什么","x":"接着看什么 为什么是它 27 扩展生态 按契约 / 实现 / 装配三层理解这些 artifact 的位置 36A 集成落地手册 把 artifact 真正接起来：Nacos / Higress / Scheduler / Studio / Training / Chat Completions 附录 E 勘误汇总 artifact 名、构造器、默认值与文档不一致时的核对入口 附录 D 源码地图 找不到扩展模块时，先看它在 core / harness 还是 extensions 表里的 artifactId 以各模块 pom.xml 为准；starter 只列正文覆盖到的 10 个， 仓库里另有 admin 、 jev 等 starter，未在 00–36 章展开。"}]);
